"""Motion generated by deciding, each frame, what the body should do next.

This replaces the generator, not the pipeline. The flywheel never defined what a
candidate *is* -- it calls something that returns a :class:`ClipResult` and then
captures, judges, ranks and repairs it -- so a different way of producing that
clip drops into the same loop.

WHAT THE OLD GENERATOR DID

    prompt -> plan_motion -> 7 phase primitives -> interpolate -> simulate

``PrimitiveKind`` is a vocabulary of *phases* (reach, preshape, contact, close,
lift, hold, recover), chosen once, before anything is observed, and the compiler
never calls the planner back. Physics ran afterwards and changed nothing. Five
"candidates" were the same program with the elbow swung a few degrees.

That is why the hand closed on a timer rather than on the object being between
its fingers, why the grip shape was fixed before the object was seen, and why
the plan was identical for every object. Those were not three bugs.

WHAT THIS DOES

    prompt
      -> a plan of what must be done, as ordered low-level steps
      -> each step as a Talmy product: FIGURE, GROUND, PATH, MOTION
      -> each frame: sense the situation, choose which primitive each body part
         should run this instant to advance the current product's goal

The primitives are the *per-part moves* in ``config/body_parts.v1.json`` -- 314
of them, which until now nothing in the motion path read. They are the controls;
the selector is what drives them.

WHAT IS AND IS NOT DECIDED BY A MODEL

The per-frame chooser is an interface, :class:`MoveSelector`, with two
implementations. :class:`GreedySelector` scores each candidate move by how much
it would reduce the current step's measured error, which is deterministic and
testable and needs no model. A VLM selector implements the same interface and
sees the same sensor readings. The architecture is the closed loop; which mind
sits in it is a separate choice, and pretending a greedy search is a VLM would
make the loop untestable.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable, Protocol

import numpy as np

from .body_parts import move_rotations, moves_for
from .kinematics import rig_kinematics
from .models import BonePose, Hand, SceneManifest, SceneObject, Vec3
from .talmy import MotionSituation, path_contour

#: Parts the selector may drive, and the moves it may choose for each. Kept to
#: the acting arm and hand: a grab that re-solves the legs every frame spends
#: its whole budget deciding not to move them.
def acting_parts(hand: Hand) -> tuple[str, ...]:
    side = hand.value
    return (
        f"{side}_shoulder",
        f"{side}_elbow",
        f"{side}_wrist",
        f"{side}_thumb",
        f"{side}_index",
        f"{side}_middle",
        f"{side}_ring",
        f"{side}_little",
    )


#: The one primitive that is solved rather than named. A reach is coordinated by
#: definition -- shoulder, elbow and wrist move together toward a point -- and
#: composing it from independently chosen per-part poses is a description of a
#: reach rather than the thing itself. Named like any other move so the trace,
#: the selector interface and the flywheel do not have to know the difference.
AIM_AT_FIGURE = "aim_at_figure"


def _aim_rotations(
    hand: Hand, sensing: Sensing, amplitude: float
) -> dict[str, Any]:
    """Arm rotations that aim the hand a fraction of the way to the object."""
    from .models import PrimitiveParameters, Vec3
    from .primitives import arm_pose_from_target, shoulder_position

    aim = _aim_point(hand, sensing, amplitude)
    arm, _ = arm_pose_from_target(
        hand,
        shoulder_position(hand),
        Vec3(x=float(aim[0]), y=float(aim[1]), z=float(aim[2])),
        PrimitiveParameters(),
        present_hand=False,
    )
    return arm


def _aim_point(hand: Hand, sensing: Sensing, amplitude: float) -> np.ndarray:
    """Where to send the WRIST so the FINGERTIPS arrive at the object.

    ``arm_pose_from_target`` places the hand bone's origin, and the point being
    steered is the mean of the fingertips, which trails it by most of a hand.
    Aiming the wrist straight at the object therefore stops a hand-length short
    however well the solver does its job -- measured, the approach error sat at
    0.0901 m and would not move, which is that offset almost exactly.

    The offset is read from the pose the hand is in, not assumed, because it
    changes as the fingers curl.
    """
    positions = rig_kinematics().canonical_positions(sensing.bones)
    wrist = np.asarray(positions[f"{hand.value}Hand"], dtype=float)
    lead = sensing.convergence - wrist
    goal = sensing.object_position - lead
    # Never past the goal. An amplitude is a fraction of the way there, and
    # allowing more than 1.0 extrapolates a WORLD POSITION rather than
    # travelling further along a path: at 1.5 the wrist is sent half a metre
    # beyond the object, the arm is flung, and the hand sweeps the block off the
    # table -- measured, 124 cm, from a loop that had been leaving it untouched.
    # Overshoot belongs to the digits closing, not to the arm arriving.
    reach = float(np.clip(amplitude, 0.0, 1.0))
    return wrist + (goal - wrist) * reach


@dataclass(frozen=True)
class Sensing:
    """What the body can actually tell about its situation this frame.

    Every field is something the simulation or the kinematics measured, not
    something the plan asserted. A selector that reads only this cannot smuggle
    in knowledge of where the object was authored to be -- which is the mistake
    that let a hand close on empty air and report a grasp, because the aperture
    was being measured against the object's authored pose while the simulated
    one had been knocked 9 cm away.
    """

    bones: dict[str, BonePose]
    object_position: np.ndarray
    tip_positions: dict[str, np.ndarray]
    convergence: np.ndarray
    contact_force_n: dict[str, float]
    opposed: bool
    time_s: float
    #: Angle between where the head points and the object. The body cannot know
    #: this about itself, but it is what decides whether the next field is a
    #: fresh observation or a memory.
    #: How fast the object and the hand are travelling, m/s. Without these the
    #: body reads a still photograph: a block already sliding away looks
    #: identical to one at rest, so a controller keeps issuing the push that is
    #: moving it. Motion is not visible in a pose, only between two of them.
    object_velocity: np.ndarray = field(default_factory=lambda: np.zeros(3))
    hand_velocity: np.ndarray = field(default_factory=lambda: np.zeros(3))
    gaze_error_deg: float = 0.0
    #: Half-extents of the object, metres. A point has no faces, and a hand
    #: cannot present its palm to a point: every approach so far aimed at the
    #: object's middle, which is inside it, so contact was the approach
    #: succeeding rather than the approach failing.
    object_half_m: np.ndarray = field(
        default_factory=lambda: np.asarray([0.03, 0.04, 0.03]))
    #: False when the object is outside the field of view, in which case
    #: ``object_position`` is the last place it was SEEN, not where it is.
    in_view: bool = True

    def loaded_digits(self, threshold_n: float = 0.5) -> tuple[str, ...]:
        return tuple(
            digit
            for digit, force in sorted(self.contact_force_n.items())
            if force >= threshold_n
        )


@dataclass
class Step:
    """One Talmy product: a thing that must be true before the next step starts.

    ``error`` is what the selector minimises and ``reached`` is what ends the
    step. They are separate because a step can be close enough to advance while
    its error is still nonzero, and because a step with no measurable goal is a
    step nothing can verify -- which is the state the old ``close`` phase was in
    when it fired on elapsed time.
    """

    name: str
    situation: MotionSituation
    error: Callable[[Sensing], float]
    reached: Callable[[Sensing], bool]
    active_parts: tuple[str, ...]
    #: Actions that suit this stage's goal, empty meaning any. Separate from
    #: ``active_parts`` because acting with the right limb is not the same as
    #: doing the right thing with it: reaching and standing off both drive the
    #: arm, and only one of them belongs in a stage that must not touch.
    allows: tuple[str, ...] = ()
    #: What this stage's goal actually demands, in numbers. Shown to a selector
    #: so it can tell "done" from "not done" rather than inferring a threshold
    #: from readings: told only that the aperture stood at 68.5 degrees and the
    #: fingertips were 0.107 m out, a model widened the aperture fourteen times
    #: while the distance never moved. It could see both numbers and neither
    #: target, so it worked the half that was already satisfied.
    requires: dict[str, Any] = field(default_factory=dict)
    #: Frames to spend before giving up and advancing anyway. A step that cannot
    #: be reached must not stall the whole motion silently.
    budget_frames: int = 45
    #: Frames without progress before the attempt is called off, 0 meaning the
    #: module default. A step that spans the whole task needs a wider window
    #: than one that only has to close a gap: three seconds of no measurable
    #: gain is a stuck reach, but it is an ordinary pause in a grasp.
    stall_frames: int = 0

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "figure": self.situation.figure,
            "path": self.situation.path,
            "motion": self.situation.motion,
            "ground": self.situation.ground,
            "active_parts": list(self.active_parts),
            "budget_frames": self.budget_frames,
        }


class MoveSelector(Protocol):
    """Chooses which primitive each active part runs this frame."""

    def choose(
        self, sensing: Sensing, step: Step, candidates: dict[str, tuple[str, ...]]
    ) -> dict[str, tuple[str, float]]:
        """Return, per part, the move to run and how much of it."""
        ...


def _tips(hand: Hand) -> dict[str, str]:
    side = hand.value
    return {
        digit: f"{side}{digit.title()}Distal"
        for digit in ("thumb", "index", "middle", "ring", "little")
    }


def sense(
    bones: dict[str, BonePose],
    hand: Hand,
    object_position: np.ndarray,
    contact_force_n: dict[str, float],
    opposed: bool,
    time_s: float,
    object_velocity: np.ndarray | None = None,
    hand_velocity: np.ndarray | None = None,
    object_half_m: np.ndarray | None = None,
) -> Sensing:
    """Read the situation from the pose and the running simulation."""
    positions = rig_kinematics().canonical_positions(bones)
    tips = {
        digit: np.asarray(positions[bone], dtype=float)
        for digit, bone in _tips(hand).items()
    }
    stack = np.vstack(list(tips.values()))
    return Sensing(
        bones=bones,
        object_half_m=(
            np.asarray([0.03, 0.04, 0.03]) if object_half_m is None
            else np.asarray(object_half_m, dtype=float)
        ),
        object_position=np.asarray(object_position, dtype=float),
        tip_positions=tips,
        convergence=stack.mean(axis=0),
        contact_force_n=dict(contact_force_n),
        opposed=bool(opposed),
        time_s=float(time_s),
        object_velocity=(
            np.zeros(3) if object_velocity is None
            else np.asarray(object_velocity, dtype=float)
        ),
        hand_velocity=(
            np.zeros(3) if hand_velocity is None
            else np.asarray(hand_velocity, dtype=float)
        ),
    )


#: A fingertip rests this far from the surface when the digit is touching it:
#: the collision capsules are 6.5-7.5 mm in radius, so a tip AT the surface is
#: already pressed into it by its own thickness.
_CONTACT_STANDOFF_M = 0.007


def _surface_distance(
    point: np.ndarray, figure: SceneObject, observed_centre: np.ndarray
) -> float:
    """Distance from a point to the object's surface, where the object IS.

    ``observed_centre`` comes from the running simulation rather than the
    scene's authored transform. Measuring against the authored pose is how a
    hand closing on empty air reported a grasp: the simulated block had been
    knocked 9 cm away and every geometric number was still being taken against
    the place it started.
    """
    half = np.asarray(
        [figure.dimensions_m.x, figure.dimensions_m.y, figure.dimensions_m.z],
        dtype=float,
    ) * 0.5
    delta = np.abs(np.asarray(point, dtype=float) - np.asarray(observed_centre, dtype=float))
    outside = np.maximum(delta - half, 0.0)
    inside = float(np.max(delta - half))
    return float(np.linalg.norm(outside)) if np.any(outside > 0) else inside


#: Half-angle of usable sight. Beyond this the object is not being looked at and
#: its position is a memory rather than an observation.
FIELD_OF_VIEW_DEG = 35.0


def observe(
    bones: dict[str, BonePose],
    hand: Hand,
    true_position: np.ndarray,
    remembered: np.ndarray | None,
    contact_force_n: dict[str, float],
    opposed: bool,
    time_s: float,
    object_velocity: np.ndarray | None = None,
    hand_velocity: np.ndarray | None = None,
    object_half_m: np.ndarray | None = None,
) -> Sensing:
    """Sense the situation, seeing the object only when looking at it.

    Until now the loop read the object's exact position out of the simulation
    every frame regardless of where the head pointed, which is not vision. It
    also made the head pointless: nothing the neck did changed what the body
    knew, so a selector had no reason to look anywhere, and no way to notice it
    had overshot.

    Here the position is an OBSERVATION when the object is within the field of
    view and the last remembered one otherwise. Looking becomes something the
    controller has to do in order to act well, which is the only way a gaze
    primitive can earn its place rather than being decoration.
    """
    from .gaze_controller import gaze_error_deg

    off_axis = gaze_error_deg(bones, true_position) if bones else 180.0
    seen = off_axis <= FIELD_OF_VIEW_DEG
    position = true_position if seen else (
        remembered if remembered is not None else true_position
    )
    # The angle to the BELIEVED position, not the true one. Reporting the true
    # off-axis angle while the object is out of view hands the body a bearing to
    # something it cannot see -- ground truth leaking in through the one field
    # whose whole purpose is to say whether the truth is available. A head knows
    # where it is pointing and where it last saw something; it does not know
    # where an unseen thing has moved to.
    believed_off_axis = (
        off_axis if seen or not bones
        else float(gaze_error_deg(bones, position))
    )
    reading = sense(bones, hand, position, contact_force_n, opposed, time_s,
                    object_velocity, hand_velocity,
                    object_half_m=object_half_m)
    return Sensing(
        bones=reading.bones,
        object_position=reading.object_position,
        tip_positions=reading.tip_positions,
        convergence=reading.convergence,
        contact_force_n=reading.contact_force_n,
        opposed=reading.opposed,
        time_s=reading.time_s,
        # An unseen object has no measurable velocity. Motion is read BETWEEN
        # observations, so when there are no observations there is no reading --
        # only the memory of where it was, which is already object_position.
        object_velocity=(
            reading.object_velocity if seen else np.zeros(3)
        ),
        hand_velocity=reading.hand_velocity,
        gaze_error_deg=believed_off_axis,
        # Carried through. It was being dropped here, so every closed-loop
        # reading fell back to the default half-extents of 3 x 4 x 3 cm --
        # which happen to match the authored block exactly, so nothing looked
        # wrong until the object was a different size. That is why the
        # robustness sweep failed on the 4 cm and 8 cm blocks: the hand was
        # sizing its grip to a block that was not there.
        object_half_m=reading.object_half_m,
        in_view=bool(seen),
    )


#: What acting blind costs, in metres of equivalent error. Priced so that
#: turning to look wins over creeping toward a remembered position, but never
#: over a grasp already in hand.
_BLIND_PENALTY_M = 0.12


def _blind_cost(sensing: Sensing) -> float:
    """Charge for acting on a memory rather than an observation.

    Switched back on now that something in the loop actually looks at a picture.
    Where the head points decides what the model is SHOWN, so turning to face
    the work is no longer decoration -- it is the difference between the brain
    seeing the object and seeing the table.

    It was briefly zeroed while the selector was a numeric search, which was
    right at the time: a perception constraint with no perception is a handicap,
    denying the controller information it has no way to recover. With a VLM the
    trade reverses, and it tracked well when it was on -- the head reached 9
    degrees off axis and held there.

    This charged for acting on a remembered position rather than an observed
    one, and the gaze gate above degraded the position estimate whenever the
    head pointed elsewhere. Both were built for a VLM that is not there: the
    selector is a numeric search over Sensing, no image is rendered anywhere in
    this loop, and nothing consumes a picture.

    Without a seeing component the pair is a handicap and nothing else -- the
    controller is denied information it has no way to recover, and the neck
    primitives it chooses to recover it are decoration. Sighted runs reached 1
    of 4 goals against 2 of 4, entirely from the degradation.

    Kept as a seam rather than deleted. FIELD_OF_VIEW_DEG, ``observe`` and the
    look primitives all still work; restoring the constraint is putting this
    penalty back once there is something that renders a frame and decides from
    it. Turning it on before then only makes the body worse at its task in
    exchange for realism nothing acts on.
    """
    if sensing.in_view:
        # Still pay a little for looking off-centre, so the gaze tracks rather
        # than catching the object at the edge of the frame.
        return _BLIND_PENALTY_M * 0.15 * min(
            1.0, sensing.gaze_error_deg / max(FIELD_OF_VIEW_DEG, 1e-6))
    return _BLIND_PENALTY_M


def _free_step(situation, scene, hand):
    """One open step: do the task. No stages, no gates, no thresholds of mine.

    Every goal written for this task had a way of being satisfied without doing
    it -- a shape reachable while touching nothing, a gate that demanded the
    grip before permitting the grip, a distance measured to a point inside the
    object. A selector that writes its own plan should not then be marched
    through someone else's, so this asks only for the thing actually wanted:
    the object off the surface.
    """
    figure = scene.object_by_id(situation.figure)
    if figure is None:
        raise ValueError(f"figure {situation.figure!r} is not in the scene")
    target = float(figure.transform.translation.y) + 0.12

    def error(s):
        """How far this is from a held, lifted object.

        The task alone -- the object's height -- is constant through the reach
        and the whole of the grasp, so a loop watching only that sees no
        progress from the first frame and calls the attempt off before the hand
        has arrived. The approach term is here for the stall detector's benefit
        and nothing else: it shapes when the loop gives up, never what the
        selector is allowed to do.
        """
        gap = float(np.linalg.norm(s.convergence - s.object_position))
        return abs(target - float(s.object_position[1])) + gap

    return Step(
        name="pick up the object",
        situation=situation,
        error=error,
        reached=lambda s: float(s.object_position[1]) >= target - 0.01,
        active_parts=_all_parts(hand),
        allows=(),
        requires={"goal": "figure_raised", "height_m": 0.12},
        budget_frames=10_000,
        # One step now spans reach, shape, close and lift. Ninety frames of no
        # measurable gain is a stuck reach; across a whole grasp it is a pause.
        stall_frames=450,
    )


def _all_parts(hand: Hand) -> tuple[str, ...]:
    """Every part the body can drive. The model decides what is relevant."""
    side = hand.value
    return (
        f"{side}_shoulder", f"{side}_elbow", f"{side}_wrist",
        f"{side}_thumb", f"{side}_index", f"{side}_middle",
        f"{side}_ring", f"{side}_little", "neck", "head",
    )


def steps_from_skill(
    situation: MotionSituation,
    scene: SceneManifest,
    hand: Hand,
    skill: str,
) -> list[Step]:
    """Turn a planning template into steps with goals the body can sense.

    The decomposition used to be four hand-written steps inside this module,
    which meant a second skill needed a second function. Now the stages, their
    order and their goals come from ``config/skills/<name>.v1.json`` and this
    only knows how to measure the four goal kinds.
    """
    from .skills import aperture_orthogonality_deg, opposition_pairs, skill_template

    figure = scene.object_by_id(situation.figure)
    if figure is None:
        raise ValueError(f"figure {situation.figure!r} is not in the scene")
    template = skill_template(skill)
    side = hand.value
    groups = {
        "arm": (f"{side}_shoulder", f"{side}_elbow", f"{side}_wrist"),
        "digits": tuple(
            f"{side}_{d}" for d in ("thumb", "index", "middle", "ring", "little")),
        "gaze": ("neck", "head"),
        "torso": ("spine", "root"),
    }
    span = float(np.linalg.norm([
        figure.dimensions_m.x, figure.dimensions_m.y, figure.dimensions_m.z]))
    start_height = float(figure.transform.translation.y)

    def _tip_gap(s: Sensing) -> float:
        gaps = [
            abs(_surface_distance(t, figure, s.object_position) - _CONTACT_STANDOFF_M)
            for t in s.tip_positions.values()
        ]
        return float(np.mean(gaps))

    def _make(kind: str, params: dict[str, Any]):
        if kind == "hand_within":
            limit = float(params.get("distance_m", 0.02))

            def _surface_reach(s: Sensing) -> float:
                """Fingertip mean to the object's SURFACE, not its centre.

                Measured to the centre, a 5 cm goal on a block whose half-width
                is 3 cm asks the hand to sit 2 cm INSIDE it -- satisfiable only
                by driving into the block, which shoves it, which moves the
                target, which makes the controller reach again. That loop pushed
                the block 18 cm while the model correctly reported it was still
                not close enough.
                """
                return _surface_distance(s.convergence, figure, s.object_position)

            def error(s: Sensing) -> float:
                return max(0.0, _surface_reach(s) - limit) + _blind_cost(s)

            return error, (lambda s: _surface_reach(s) <= limit)

        if kind == "aperture_encapsulates":
            want = float(params.get("orthogonality_deg", 60.0))

            def error(s: Sensing) -> float:
                # Two things at once, which is the whole point of this stage:
                # the opening must stand square to the palm AND be around the
                # object. Either alone is the failure that has been recurring --
                # square but empty, or containing but flat against the palm.
                square = max(0.0, want - aperture_orthogonality_deg(s.bones, side))
                return square * 0.002 + _tip_gap(s) + _blind_cost(s)

            def reached(s: Sensing) -> bool:
                return (
                    aperture_orthogonality_deg(s.bones, side) >= want
                    and _tip_gap(s) <= float(params.get("clearance_m", 0.01)) * 3.0
                )

            return error, reached





        if kind == "thumb_and_finger_touch":
            floor = float(params.get("min_force_n", 0.3))
            want_fingers = int(params.get("fingers", 1))

            def error(s: Sensing) -> float:
                """Shape the hand until the thumb AND fingers are both on it.

                Contact is the signal that the shaping worked, and it is the
                only one that cannot be faked by geometry: every shape metric
                here has had a pose that satisfies it while touching nothing,
                and a search found each one. Orienting the hand and forming the
                Cs are a single act, not two stages that undo each other.
                """
                touched = sum(
                    1 for d in ("index", "middle", "ring", "little")
                    if s.contact_force_n.get(d, 0.0) >= floor
                )
                thumb_on = s.contact_force_n.get("thumb", 0.0) >= floor
                return (
                    object_in_grasp(s, hand)
                    + 0.04 * (0.0 if thumb_on else 1.0)
                    + 0.02 * max(0, want_fingers - touched)
                    + 0.03 * max(0.0, grip_closure(s.bones, hand))
                    + _blind_cost(s)
                )

            def reached(s: Sensing) -> bool:
                touched = sum(
                    1 for d in ("index", "middle", "ring", "little")
                    if s.contact_force_n.get(d, 0.0) >= floor
                )
                return (
                    s.contact_force_n.get("thumb", 0.0) >= floor
                    and touched >= want_fingers
                )

            return error, reached

        if kind == "palm_presented":
            want_face = float(params.get("palm_facing", 0.35))
            want_near = float(params.get("distance_m", 0.10))

            def error(s: Sensing) -> float:
                """Hand near the object AND turned so the palm faces it.

                What has to be true before closing, and all that has to be. The
                previous gate demanded the object already lie on the line
                between thumb and fingers, which an OPEN hand cannot satisfy --
                that line sits about 5 cm off the block however the arm is
                placed, and closing the C is the thing that brings it in. So it
                gated the grip on a condition only the grip could produce, and
                the run spent twenty-six calls alternating reach and rotate
                without ever advancing.
                """
                from .grasp_aperture import _palm_normal

                toward = s.object_position - s.convergence
                span = float(np.linalg.norm(toward))
                near = max(0.0, span - want_near)
                try:
                    facing = float(np.dot(_palm_normal(s.bones, hand.value),
                                          toward / span)) if span > 1e-9 else -1.0
                except Exception:  # noqa: BLE001
                    facing = -1.0
                return near + 0.15 * max(0.0, want_face - facing) + _blind_cost(s)

            def reached(s: Sensing) -> bool:
                from .grasp_aperture import _palm_normal

                toward = s.object_position - s.convergence
                span = float(np.linalg.norm(toward))
                if span > want_near:
                    return False
                try:
                    return float(np.dot(_palm_normal(s.bones, hand.value),
                                        toward / span)) >= want_face
                except Exception:  # noqa: BLE001
                    return False

            return error, reached

        if kind == "object_between_digits":
            want = float(params.get("inside_m", 0.02))

            def error(s: Sensing) -> float:
                """How far the object is from being INSIDE the hand's opening.

                The approach used to ask for the fingertips within a distance of
                the object and stop there, which leaves the object beside the
                hand rather than in it -- and a hand then closes on the space
                next to what it is trying to hold. Measured: closing from that
                pose drove the object from 3.5 cm to 7.0 cm out of the grasp.
                """
                return object_in_grasp(s, hand) + _blind_cost(s)

            return error, (lambda s: object_in_grasp(s, hand) <= want)


        if kind == "whole_hand_c":
            want = float(params.get("closure", -0.4))

            def error(s: Sensing) -> float:
                """Every finger in a C on the object, which is the grip itself."""
                return (
                    max(0.0, grip_closure(s.bones, hand) - want)
                    + object_in_grasp(s, hand)
                    + _blind_cost(s)
                )

            return error, (
                lambda s: grip_closure(s.bones, hand) <= want
                and object_in_grasp(s, hand) <= 0.03
            )

        if kind == "thumb_finger_c":
            want_facing = float(params.get("pad_facing", 0.7))
            want_gap = float(params.get("contact_m", 0.012))

            def error(s: Sensing) -> float:
                """How far the hand is from a closed C between thumb and index.

                Replaces the opposition-pair goal, which asked for a reading
                that only appears AFTER a grip exists and so could not be worked
                toward: before contact its value was a constant, and after
                contact the stage was already over. Across fifteen runs it never
                once read above zero.

                A C is a shape, and a shape can be approached. The thumb's pad
                faces the index's, the two are on either side of the object, and
                both are close enough to press it. Get the shape and the forces
                follow; chase the forces and there is nothing to steer by.
                """
                shape = c_shape(s.bones, hand)
                thumb = s.tip_positions.get("thumb")
                index = s.tip_positions.get("index")
                if thumb is None or index is None:
                    return 1.0
                gap_t = _surface_distance(thumb, figure, s.object_position)
                gap_i = _surface_distance(index, figure, s.object_position)
                return (
                    # The rays must close on each other, and point at each other.
                    shape["gap_m"]
                    + 0.08 * max(0.0, want_facing - shape["converging"])
                    + max(0.0, gap_t - want_gap)
                    + max(0.0, gap_i - want_gap)
                    + _blind_cost(s)
                )

            def reached(s: Sensing) -> bool:
                thumb = s.tip_positions.get("thumb")
                index = s.tip_positions.get("index")
                if thumb is None or index is None:
                    return False
                shape = c_shape(s.bones, hand)
                return (
                    shape["converging"] >= want_facing
                    and shape["gap_m"] <= want_gap * 2.5
                    and _surface_distance(thumb, figure, s.object_position) <= want_gap
                    and _surface_distance(index, figure, s.object_position) <= want_gap
                )

            return error, reached

        if kind == "opposition_pairs":
            want = int(params.get("pairs", 1))
            force = float(params.get("min_force_n", 0.5))

            def error(s: Sensing) -> float:
                have = opposition_pairs(s.contact_force_n, force)
                if have >= want:
                    return 0.0
                # Where the thumb IS, not only whether it has touched. Without
                # this the error was contact distance plus a constant, so a
                # thumb beside the fingers scored the same as one across from
                # them and nothing could work toward a pair.
                across = thumb_opposition_score(s)
                return (
                    _tip_gap(s)
                    + 0.04 * (1.0 - across)
                    + 0.03 * max(0, want - have)
                    + _blind_cost(s)
                )

            return error, (lambda s: opposition_pairs(s.contact_force_n, force) >= want)

        if kind == "figure_raised":
            height = float(params.get("height_m", 0.12))

            def error(s: Sensing) -> float:
                return abs((start_height + height) - float(s.object_position[1]))

            return error, (
                lambda s: float(s.object_position[1]) >= start_height + height - 0.01)

        raise ValueError(f"no measurement for goal {kind!r}")

    steps: list[Step] = []
    for stage in template["stages"]:
        error, reached = _make(stage["goal"], stage.get("goal_params", {}))
        parts: tuple[str, ...] = ()
        for group in stage.get("acts_with", ()):
            parts += groups.get(group, ())
        steps.append(Step(
            name=stage["name"],
            situation=MotionSituation(
                figure=situation.figure if stage["goal"] == "figure_raised" else "hand",
                path=stage.get("path", "TO"),
                motion=stage.get("motion", "MOVE"),
                ground=situation.figure,
                manner=stage.get("manner"),
                source_text=stage["name"]),
            error=error,
            reached=reached,
            # Every primitive, at every stage. Restricting the menu per stage
            # was meant to stop the model choosing something inappropriate, and
            # it did -- along with stopping it choosing the thing that would
            # have worked. A stage that forbids curling a finger cannot form a C
            # however well the model reasons.
            active_parts=_all_parts(hand),
            allows=tuple(stage.get("allows", ())),
            requires=dict(stage.get("goal_params", {}), goal=stage["goal"]),
            budget_frames=int(stage.get("budget_frames", 45)),
        ))
    return steps


def decompose(
    situation: MotionSituation,
    scene: SceneManifest,
    hand: Hand,
) -> list[Step]:
    """The overall product, broken into the steps that achieve it.

    "pick up box" is one Talmy product -- MOVE the block OFF its support -- and
    it is not directly actionable: nothing about OFF says how a hand gets there.
    It decomposes into products that are: bring the hand TO the object, close
    AT it until it is held, then MOVE it OFF.

    Each carries its own measurable goal, so "am I done" is a reading rather
    than a stopwatch.
    """
    from .skills import resolve

    skill = resolve(situation.source_text or "")
    if skill is not None:
        # Planned from an uploadable template rather than from this function.
        return steps_from_skill(situation, scene, hand, skill)

    figure = scene.object_by_id(situation.figure)
    if figure is None:
        raise ValueError(f"figure {situation.figure!r} is not in the scene")
    side = hand.value
    #: The gaze acts throughout. "Do the task and keep your eyes on it" is one
    #: instruction, not two: without sight the position the body steers by is a
    #: memory, so looking is part of every step rather than a separate one.
    gaze = ("neck", "head")
    arm = (f"{side}_shoulder", f"{side}_elbow", f"{side}_wrist")
    digits = (f"{side}_thumb", f"{side}_index", f"{side}_middle",
              f"{side}_ring", f"{side}_little")

    contour = path_contour(situation, scene)
    lift_target = float(contour.points[-1][1])

    #: The hand must be open wider than the object before it arrives, or the
    #: approach is a fist driven through it.
    span = float(np.linalg.norm([
        figure.dimensions_m.x, figure.dimensions_m.y, figure.dimensions_m.z]))

    def _spread(s: Sensing) -> float:
        """Widest distance between any two fingertips."""
        points = list(s.tip_positions.values())
        return max(
            float(np.linalg.norm(a - b))
            for index, a in enumerate(points)
            for b in points[index + 1:]
        )

    def approach_error(s: Sensing) -> float:
        """Distance to the object, plus whatever the hand is still closed by.

        Aiming the fingertip mean at the object's centre is right -- that is
        where a cage grasp puts it -- but only for a hand already open enough to
        arrive around the object rather than into it. With the digits left at
        their rest pose the approach became a fist driven at the block, and the
        block went on the floor: 124 cm, once the arm finally reached far enough
        to touch anything at all.

        Openness is scored as a shortfall against the object's own size, so it
        stops mattering the moment the hand is wide enough, and the term never
        competes with arriving.
        """
        distance = float(np.linalg.norm(s.convergence - s.object_position))
        shortfall = max(0.0, span - _spread(s))
        return distance + shortfall + _blind_cost(s)

    #: How far clear of the object the gross reach stops. One object-span, so
    #: the hand arrives beside what it is reaching for rather than on it.
    standoff = span

    def _standoff_point(s: Sensing) -> np.ndarray:
        """A point one span short of the object, on the hand's own approach line."""
        toward = s.object_position - s.convergence
        distance = float(np.linalg.norm(toward))
        if distance < 1e-6:
            return s.object_position
        return s.object_position - (toward / distance) * standoff

    def stage_error(s: Sensing) -> float:
        """Get NEXT TO the object, open, without touching it.

        Split from the fine approach because merging them made the gross reach
        drive straight onto the block. The loop would arrive correctly -- 0.064 m,
        the closest it had managed -- and knock the block off the table on the
        way in, because nothing said where to stop. The user's own decomposition
        had this step ("ensure box is near grip") and collapsing it was the
        mistake.
        """
        distance = float(np.linalg.norm(s.convergence - _standoff_point(s)))
        shortfall = max(0.0, span - _spread(s))
        return distance + shortfall + _blind_cost(s)

    def stage_reached(s: Sensing) -> bool:
        return stage_error(s) < 0.03

    def approach_reached(s: Sensing) -> bool:
        # Within a hand's own reach of the object, not touching it yet.
        return approach_error(s) < 0.045

    def grasp_error(s: Sensing) -> float:
        """How far each fingertip is from resting on the object's surface.

        Measured against the tips, not the hand's convergence point, because the
        digits are the parts this step activates and convergence is set by the
        arm. Scored on convergence, the fingers were minimising a number they
        could not move: the error drifted UP over the whole step, 0.1240 to
        0.1255, while the hand sat still and one finger happened to touch.

        A tip should come to rest ON the surface, so the target is a small
        positive standoff rather than zero -- a tip driven to the surface itself
        is already pressed into it by the digit's own thickness -- and going
        further in is penalised as much as stopping short, since a finger inside
        the object is what MuJoCo answers by throwing it.
        """
        gaps = [
            abs(_surface_distance(tip, figure, s.object_position) - _CONTACT_STANDOFF_M)
            for tip in s.tip_positions.values()
        ]
        return float(np.mean(gaps)) + (0.0 if s.opposed else 0.03) + _blind_cost(s)

    def grasp_reached(s: Sensing) -> bool:
        # The real test, and the one the old pipeline never applied: load on
        # opposing faces. Contact alone is a shove -- measured, the palm pressed
        # this block at 50 N from one side and slid it 5 cm.
        return s.opposed and len(s.loaded_digits()) >= 2

    def lift_error(s: Sensing) -> float:
        return abs(lift_target - float(s.object_position[1]))

    def lift_reached(s: Sensing) -> bool:
        return float(s.object_position[1]) >= lift_target - 0.01

    return [
        Step(
            name="bring the hand beside the object",
            situation=MotionSituation(
                figure="hand", path="TO", motion="MOVE",
                ground=situation.figure, source_text="move the hand next to the object"),
            error=stage_error,
            reached=stage_reached,
            active_parts=arm + digits + gaze,
            budget_frames=30,
        ),
        Step(
            name="bring the hand to the object",
            situation=MotionSituation(
                figure="hand", path="TO", motion="MOVE",
                ground=situation.figure, source_text="move the hand to the object"),
            error=approach_error,
            reached=approach_reached,
            active_parts=arm + digits + gaze,
        ),
        Step(
            name="close until the object is held",
            situation=MotionSituation(
                figure="hand", path="AT", motion="BEL", manner="GRASPED",
                ground=situation.figure, source_text="close on the object"),
            error=grasp_error,
            reached=grasp_reached,
            active_parts=digits + gaze,
        ),
        Step(
            name=f"move the object {situation.path}",
            situation=situation,
            error=lift_error,
            reached=lift_reached,
            active_parts=arm + digits + gaze,
        ),
    ]


@dataclass
class GreedySelector:
    """Picks the move that most reduces the step's error, one frame ahead.

    Deterministic and cheap: each candidate is applied to the current pose and
    the error re-read, which is forward kinematics rather than a simulation
    step. It is a baseline, not the intended mind -- but it is the thing a VLM
    selector has to beat, and without it there is no way to tell whether a model
    is choosing well or the loop is carrying it.
    """

    hand: Hand
    #: Blend toward the chosen move, per frame. A move is a target pose, not a
    #: teleport; stepping straight onto it is what produced the strikes the
    #: rate limiter was added to catch.
    rate: float = 0.25

    #: Magnitudes considered per move. Without these a part can only strike the
    #: poses somebody named: over all 990 arm move combinations the hand could
    #: get no closer than 17.4 cm to the block, which no selector can repair.
    #: The same combinations carrying a magnitude reach 2.4 cm.
    amplitudes: tuple[float, ...] = (0.25, 0.5, 0.75, 1.0, 1.25, 1.5)

    def choose(
        self, sensing: Sensing, step: Step, candidates: dict[str, tuple[str, ...]]
    ) -> dict[str, tuple[str, float]]:
        chosen: dict[str, tuple[str, float]] = {}

        # A goal-directed primitive, offered to the arm alongside the named
        # poses. Scaled named poses alone are not enough and the reason is the
        # search, not the vocabulary: reaching the block needs the shoulder,
        # elbow and wrist to change TOGETHER, and choosing one part at a time
        # against the others' current pose is coordinate descent, which stops at
        # the first place where no single part can improve. Measured, that is
        # 19.9 cm out, while the best joint choice is 2.4 cm.
        #
        # Rather than search the product space every frame -- 990 combinations
        # times six magnitudes each is 200k forward-kinematics passes -- the arm
        # gets one primitive that is already coordinated: aim the hand at a
        # point. That is what a reach IS, and composing it out of "abduct this
        # much, carry that much" was always a description of a reach rather than
        # the thing itself.
        arm_parts = {f"{self.hand.value}_{p}" for p in ("shoulder", "elbow", "wrist")}
        if arm_parts & set(candidates):
            aimed = self._reach(sensing, step)
            if aimed is not None:
                chosen.update(aimed)

        for part, moves in candidates.items():
            if part in chosen:
                continue
            best: tuple[float, str, float] | None = None
            for move in moves:
                for amplitude in self.amplitudes:
                    trial = dict(sensing.bones)
                    try:
                        rotations = move_rotations(part, move, amplitude)
                    except Exception:
                        continue
                    for name, rotation in rotations.items():
                        trial[name] = BonePose(rotation=rotation)
                    probe = sense(
                        trial, self.hand, sensing.object_position,
                        sensing.contact_force_n, sensing.opposed, sensing.time_s,
                    )
                    value = step.error(probe)
                    if best is None or value < best[0]:
                        best = (value, move, amplitude)
            if best is not None:
                chosen[part] = (best[1], best[2])
        return chosen

    def _reach(
        self, sensing: Sensing, step: Step
    ) -> dict[str, tuple[str, float]] | None:
        """Aim the hand at the object, and take it only if it beats standing still.

        Returned in the same (move, amplitude) shape as any other choice, where
        the amplitude is how far along the aim to travel this frame, so the loop
        does not need to know this one came from a solver.
        """
        from .models import PrimitiveParameters, Vec3
        from .primitives import arm_pose_from_target, shoulder_position

        target = sensing.object_position
        here = step.error(sensing)
        best: tuple[float, float] | None = None
        for amplitude in self.amplitudes:
            # Aim short of, at, or past the object: past is what closes the last
            # centimetres, because the fingertips trail the wrist.
            aim = _aim_point(self.hand, sensing, amplitude)
            try:
                arm, _ = arm_pose_from_target(
                    self.hand, shoulder_position(self.hand),
                    Vec3(x=float(aim[0]), y=float(aim[1]), z=float(aim[2])),
                    PrimitiveParameters(), present_hand=False)
            except Exception:
                continue
            trial = dict(sensing.bones)
            for bone, rotation in arm.items():
                trial[bone] = BonePose(rotation=rotation)
            probe = sense(trial, self.hand, sensing.object_position,
                          sensing.contact_force_n, sensing.opposed, sensing.time_s)
            value = step.error(probe)
            if best is None or value < best[0]:
                best = (value, amplitude)
        if best is None or best[0] >= here:
            return None
        self._aim_amplitude = best[1]
        return {
            f"{self.hand.value}_{part}": (AIM_AT_FIGURE, best[1])
            for part in ("shoulder", "elbow", "wrist")
        }



# ---------------------------------------------------------------------------
# The super-primitive layer.
#
# Everything the selector may call is here, and everything here is coordinated:
# each drives several parts at once toward a goal, and each resolves down to the
# same per-bone rotations a per-part move would have produced.
#
# The loop used to choose one atomic move per part per frame, and every failure
# it hit was a coordination that choice could not express. Reaching needs the
# shoulder, elbow and wrist together -- over all 990 combinations of their named
# poses the hand could get no closer than 17.4 cm to the block, and choosing one
# part at a time stalls at 19.9 cm. Opening the hand needs five digits together.
# Opposing the thumb needs the thumb and the finger it works against. Each time,
# the coordination had to be smuggled into an error function instead of being a
# thing the controller could ask for.
#
# So the controls are high level and they map down, rather than being low level
# and hoping the selector rediscovers the map every frame.
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class SuperPrimitive:
    """A coordinated action the selector can call, with the parts it drives."""

    name: str
    parts: tuple[str, ...]
    describes: str
    solve: Callable[[Sensing, Hand, float], dict[str, Any]]

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "parts": list(self.parts), "describes": self.describes}


def _arm_parts(hand: Hand) -> tuple[str, ...]:
    side = hand.value
    return (f"{side}_shoulder", f"{side}_elbow", f"{side}_wrist")


def _digit_parts(hand: Hand) -> tuple[str, ...]:
    side = hand.value
    return tuple(f"{side}_{d}" for d in ("thumb", "index", "middle", "ring", "little"))


def _solve_reach(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Aim the FINGERTIPS at the object, a fraction of the way there."""
    from .models import PrimitiveParameters, Vec3
    from .primitives import arm_pose_from_target, shoulder_position

    # Aim at the object's SURFACE, not its centre. The centre is inside the
    # block, so aiming there commands the hand into it: measured, every
    # reach_to call in one run drove the block further across the table, 0 to
    # 25.8 cm over five calls, while the model kept correctly observing that
    # the fingertips were not yet close enough.
    aim = _aim_point(hand, sensing, amount)
    toward = sensing.object_position - sensing.convergence
    span = float(np.linalg.norm(toward))
    if span > 1e-6:
        aim = aim - (toward / span) * _SURFACE_STANDOFF_M
    arm, _ = arm_pose_from_target(
        hand, shoulder_position(hand),
        Vec3(x=float(aim[0]), y=float(aim[1]), z=float(aim[2])),
        PrimitiveParameters(), present_hand=False)
    return arm


#: How far short of the object's centre a reach stops: roughly the half-width of
#: a graspable thing, so the fingertips arrive at its face rather than its middle.
_SURFACE_STANDOFF_M = 0.035

#: How far short of the object the gross approach stops, in metres. Fixed rather
#: than derived from the action's magnitude, so the target stays put while the
#: body moves toward it.
_STANDOFF_M = 0.12


def object_faces(sensing: Sensing) -> list[tuple[np.ndarray, np.ndarray]]:
    """The object's six faces, each as (centre, outward normal)."""
    centre = np.asarray(sensing.object_position, dtype=float)
    half = np.asarray(sensing.object_half_m, dtype=float)
    faces: list[tuple[np.ndarray, np.ndarray]] = []
    for axis in range(3):
        for sign in (+1.0, -1.0):
            normal = np.zeros(3)
            normal[axis] = sign
            faces.append((centre + normal * half[axis], normal))
    return faces


def _palm_frame(sensing: Sensing, hand: Hand):
    """Where the palm is and which way it faces, or None if it cannot be read."""
    from .models import ClipFrame
    from .physics import _frame_hand_landmarks, _palm_transform

    try:
        landmarks = _frame_hand_landmarks(
            ClipFrame(time_s=0.0, bones=sensing.bones, objects={}), hand)
        centre, rotation = _palm_transform(landmarks, hand)
    except Exception:  # noqa: BLE001
        return None
    centre = np.asarray(centre, dtype=float)
    # Not the middle of the palm: the pad across the top of it, at the base of
    # the fingers, where the calluses are. That is the surface a held object
    # actually rests against, and it is roughly a third of the palm's length
    # further up than its geometric centre. Steering the middle parks the
    # object level with the heel of the hand, below everything that closes on
    # it, which is a grip that has to work uphill.
    try:
        knuckles = np.mean([
            np.asarray(landmarks[f"{hand.value}{digit}Proximal"], dtype=float)
            for digit in ("Index", "Middle", "Ring", "Little")
        ], axis=0)
        centre = centre + (knuckles - centre) * _PALM_PAD_FRACTION
    except Exception:  # noqa: BLE001
        pass
    return centre, np.asarray(rotation[:, 2], dtype=float)


def chosen_face(sensing: Sensing, hand: Hand):
    """The face the hand should present its palm to.

    Whichever the palm is already most in front of. This is a default, not a
    decision: the selector can name a different one, and which face a thing
    should be picked up by is exactly the sort of judgement it is there to make.
    """
    frame = _palm_frame(sensing, hand)
    if frame is None:
        return None
    palm, _normal = frame
    best = None
    for face_centre, face_normal in object_faces(sensing):
        toward = palm - face_centre
        size = float(np.linalg.norm(toward))
        if size < 1e-9:
            continue
        score = float(np.dot(toward / size, face_normal))
        if best is None or score > best[0]:
            best = (score, face_centre, face_normal)
    return None if best is None else (best[1], best[2])


def palm_to_object_m(sensing: Sensing, hand: Hand) -> float:
    """Metres from the palm's centre to the object's surface.

    The quantity that actually decides whether a grasp is possible, and it was
    not being measured. The plan steered on fingertip-to-CENTRE distance, which
    is minimised by driving the fingers into the object, and which no control
    could improve past 6.3 cm anyway because the fingertips trail the wrist by
    most of a hand.
    """
    frame = _palm_frame(sensing, hand)
    if frame is None:
        return 1.0
    palm, _normal = frame
    offset = np.abs(palm - np.asarray(sensing.object_position, dtype=float))
    outside = np.maximum(offset - np.asarray(sensing.object_half_m, dtype=float), 0.0)
    return float(np.linalg.norm(outside))


def palm_facing(sensing: Sensing, hand: Hand) -> float:
    """+1 when the palm looks straight at its face, -1 when it looks away.

    The palm's outward normal against the inward normal of the face being
    approached. A hand can be 2 cm from a block and unable to hold it because it
    arrived edge-on; this is the difference, and nothing measured it.
    """
    frame = _palm_frame(sensing, hand)
    face = chosen_face(sensing, hand)
    if frame is None or face is None:
        return 0.0
    _palm, normal = frame
    _centre, face_normal = face
    return float(np.dot(normal, -face_normal))


#: How far up the palm the contact pad sits, as a fraction of the distance from
#: the palm's centre to the knuckles. The distal transverse pad, not the middle.
_PALM_PAD_FRACTION = 0.6

#: Contact force at which the ARM stops advancing, newtons. Above the digits'
#: settling force, so brushing the object while arriving does not halt the
#: approach, but real contact does.
_ARM_STOP_FORCE_N = 2.5

#: Object speed above which the approach is pushing rather than arriving,
#: m/s. Nothing that is being reached for should be moving.
_PUSHING_SPEED_M_S = 0.02

#: How far off the face the palm pad is asked to stop, metres.
#:
#: Small on purpose. The pad is at the knuckles and the digits reach most of a
#: hand beyond it, so a standoff measured from the pad decides how far INTO the
#: opening the object ends up. At 4 cm the block sat out by the fingertips: the
#: grip formed, and closing then pushed it straight back out of the hand --
#: object-to-grasp-line went 4.7 cm to 8.2 while the digits shut. The object has
#: to be between the digits before anything closes, which means the pad comes
#: almost to the face.
_FACE_STANDOFF_M = 0.015


def _solve_move_to(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Carry the palm to a face of the object, arriving square to it.

    The replacement for aiming at the object's middle. A face is chosen, a point
    is taken a little way out along its normal, and the arm carries the PALM
    there -- so the approach ends with the palm parked in front of a surface
    rather than with the fingers buried in the object, which is what aiming at a
    centre necessarily does.

    Order matters here and cost a measured mistake. Squaring the wrist to the
    face MOVES the palm, so doing it after the arm solve undoes the placement:
    the first version left the palm further from the block than it started,
    10.5 cm out to 11.4. The wrist is therefore chosen first and held fixed
    while the arm converges onto the palm target.

    The arm solver places the wrist, and the palm trails it by most of a hand
    and swings as the arm turns, so one linear correction does not land. The
    remaining error is fed back instead, which closes it in a few passes.
    """
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose
    from .analysis.anatomy.rom import rom_limit
    from .models import PrimitiveParameters, Quat, Vec3
    from .primitives import arm_pose_from_target, shoulder_position

    # A guarded move, for the ARM. Once the hand is genuinely touching the
    # object, driving the wrist further forward pushes the digits through it:
    # the same mistake the digits made before closure was gated on force, one
    # level up and with far more leverage behind it. Measured in run 000501,
    # with the standoff at 1.5 cm and move_to chosen six times, the thumb ended
    # 18.9 mm INSIDE a 60 mm block reporting 80 N while the index and ring sat
    # 5-7 cm away -- the arm had carried the hand through what it was reaching
    # for.
    #
    # The threshold sits above the digits' own settling force, so brushing the
    # object while arriving does not stop the approach; only real contact does.
    if max(sensing.contact_force_n.values(), default=0.0) >= _ARM_STOP_FORCE_N:
        return {}

    # And approaching an object you are already holding drives the hand through
    # the thing it is carrying: move_to aims the palm at a FACE, and while
    # holding, that face is under the fingers. Run 000508 had a three-digit
    # grasp, lifted it correctly, then chose move_to and tore the block out of
    # its own hand.
    if holding_object(sensing):
        return {}

    # And stop if the object is RUNNING AWAY. Force is the wrong sensor for
    # this: shoving a 0.25 kg block across a table barely registers, and in run
    # 000510 the approach moved it 9.5 cm without once crossing the 2.5 N stop.
    # The block's own speed says it directly. The hand then formed a genuinely
    # strong grasp -- 17.7 N on the thumb, three digits -- on an object that was
    # already sliding, and lost it during the lift.
    if float(np.linalg.norm(sensing.object_velocity)) >= _PUSHING_SPEED_M_S:
        return {}

    face = chosen_face(sensing, hand)
    frame = _palm_frame(sensing, hand)
    if face is None or frame is None:
        return {}
    face_centre, face_normal = face
    palm, _normal = frame
    goal = face_centre + face_normal * _FACE_STANDOFF_M
    reach = float(np.clip(amount, 0.0, 1.0))
    want = palm + (goal - palm) * reach

    bone = f"{hand.value}Hand"
    wrist_frame = all_frames().get(bone)

    def read(bones: dict[str, BonePose]):
        return _palm_frame(
            Sensing(bones=bones, object_position=sensing.object_position,
                    tip_positions=sensing.tip_positions,
                    convergence=sensing.convergence, contact_force_n={},
                    opposed=False, time_s=sensing.time_s,
                    object_half_m=sensing.object_half_m), hand)

    # 1. Which way the wrist must be turned for the palm to face the surface.
    wrist_rotation = None
    if wrist_frame is not None:
        flex_low, flex_high = rom_limit(bone, "flexion").typical_deg
        abduct_low, abduct_high = rom_limit(bone, "abduction").typical_deg
        best: tuple[float, Any] | None = None
        for flex in np.linspace(flex_low, flex_high, 12):
            for abduct in np.linspace(abduct_low, abduct_high, 6):
                quaternion = compose(
                    DofAngles(math.radians(float(flex)),
                              math.radians(float(abduct)), 0.0), wrist_frame)
                rotation = Quat(x=quaternion[0], y=quaternion[1],
                                z=quaternion[2], w=quaternion[3])
                trial = dict(sensing.bones)
                trial[bone] = BonePose(rotation=rotation)
                reading = read(trial)
                if reading is None:
                    continue
                score = float(np.dot(reading[1], -face_normal))
                if best is None or score > best[0]:
                    best = (score, rotation)
        if best is not None:
            wrist_rotation = best[1]

    # 2. With the hand held at that angle, walk the arm until the palm lands.
    positions = rig_kinematics().canonical_positions(sensing.bones)
    aim = np.asarray(positions[bone], dtype=float) + (want - palm)
    arm: dict[str, Any] = {}
    for _pass in range(6):
        arm, _ = arm_pose_from_target(
            hand, shoulder_position(hand),
            Vec3(x=float(aim[0]), y=float(aim[1]), z=float(aim[2])),
            PrimitiveParameters(), present_hand=False)
        if wrist_rotation is not None:
            arm[bone] = wrist_rotation
        trial = dict(sensing.bones)
        for name, rotation in arm.items():
            trial[name] = BonePose(rotation=rotation)
        reading = read(trial)
        if reading is None:
            break
        remaining = want - reading[0]
        if float(np.linalg.norm(remaining)) < 0.004:
            break
        aim = aim + remaining
    return arm

def _solve_stand_off(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Aim short of the object, leaving room to arrive without touching."""
    from .models import PrimitiveParameters, Vec3
    from .primitives import arm_pose_from_target, shoulder_position

    toward = sensing.object_position - sensing.convergence
    distance = float(np.linalg.norm(toward))
    if distance < 1e-6:
        return {}
    # The standoff distance is FIXED; ``amount`` says how far along to travel
    # toward it, not where it is. Scaling the target by the magnitude made the
    # goalpost move every time the magnitude changed, and the hand oscillated
    # between 15 and 20 cm out for ten straight decisions -- chasing a point it
    # displaced each time it acted. A control whose target depends on how hard
    # you pull it cannot converge.
    goal = sensing.object_position - (toward / distance) * _STANDOFF_M
    wrist = np.asarray(
        rig_kinematics().canonical_positions(sensing.bones)[f"{hand.value}Hand"],
        dtype=float)
    lead = sensing.convergence - wrist
    # Travel a fraction of the way to a fixed goal.
    aim = wrist + ((goal - lead) - wrist) * float(np.clip(amount, 0.0, 1.0))
    arm, _ = arm_pose_from_target(
        hand, shoulder_position(hand),
        Vec3(x=float(aim[0]), y=float(aim[1]), z=float(aim[2])),
        PrimitiveParameters(), present_hand=False)
    return arm


def _solve_digits(hand: Hand, curl: float, opposition: float) -> dict[str, Any]:
    from .force_closure import digit_rotations

    return digit_rotations(
        hand, {d: curl for d in ("thumb", "index", "middle", "ring", "little")}, opposition)


def _solve_open(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Open the hand into an aperture that stands square to the palm.

    ``amount`` travels toward the pose that maximises that squareness, measured
    over the thumb's own degrees of freedom rather than guessed: the angle peaks
    at 73.5 degrees near a thumb curl of 0.45 with the thumb barely opposed, and
    falls to about 50 as opposition rises past 0.9.

    That mattered because this primitive used to pin opposition at 0.9, chosen
    to keep the thumb out of the corridor during the APPROACH, and was then
    reused for a stage that runs with the hand already at the object. Capped at
    roughly 50 degrees against a goal of 60, the model asked for a wider
    aperture eight times in a row -- correctly, and to no effect, because the
    primitive could not produce one. It is the stage's own goal; the primitive
    that serves it should be aimed at it.
    """
    reach = float(np.clip(amount, 0.0, 1.0))
    return _solve_digits(
        hand,
        curl=0.05 + 0.40 * reach,
        # Enough to keep the thumb off the fingers' side, low enough that the
        # aperture can stand up. 0.3 measures 68.8 degrees where 0.9 gives 53.2.
        opposition=0.3,
    )




def _thumb_move(move: str):
    """A primitive that runs one named thumb move from the vocabulary."""

    def solve(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
        from .body_parts import move_rotations

        return move_rotations(
            f"{hand.value}_thumb", move, float(np.clip(amount, 0.0, 1.5))
        )

    return solve


def _curl_one(digit: str):
    """A primitive that curls exactly one finger."""

    def solve(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
        from .force_closure import digit_rotations

        held = {
            d: 0.35 for d in ("thumb", "index", "middle", "ring", "little")
        }
        held[digit] = 0.1 + 0.8 * float(np.clip(amount, 0.0, 1.0))
        rotations = digit_rotations(hand, held, opposition=0.3)
        stem = digit.title()
        # Only this finger's bones, so the others keep whatever they were doing.
        return {k: v for k, v in rotations.items() if stem in k}

    return solve



#: The bones of each digit, base first. The thumb has a metacarpal where the
#: fingers have an intermediate, which is the only difference between them and
#: not a reason for it to have its own vocabulary.
_DIGIT_CHAINS = {
    "thumb": ("Metacarpal", "Proximal", "Distal"),
    "index": ("Proximal", "Intermediate", "Distal"),
    "middle": ("Proximal", "Intermediate", "Distal"),
    "ring": ("Proximal", "Intermediate", "Distal"),
    "little": ("Proximal", "Intermediate", "Distal"),
}

#: How a curl distributes along a digit, base to tip. A finger does not bend
#: equally at every joint -- the knuckle carries most of it -- and a uniform
#: bend gives the claw shape rather than the hook that holds things.
_CURL_SHARE = (1.0, 0.9, 0.6)


def _digit_bones(hand: Hand, digit: str) -> tuple[str, ...]:
    return tuple(
        f"{hand.value}{digit.title()}{segment}"
        for segment in _DIGIT_CHAINS[digit]
    )


def _digit_rotation(bone: str, flex_fraction: float, sweep_fraction: float):
    """One bone's delta, as a fraction of its own range on each axis."""
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose
    from .analysis.anatomy.rom import rom_limit
    from .models import Quat

    frame = all_frames().get(bone)
    if frame is None:
        return None

    def angle(dof: str, fraction: float) -> float:
        if abs(fraction) < 1e-9:
            return 0.0
        try:
            low, high = rom_limit(bone, dof).typical_deg
        except Exception:  # noqa: BLE001
            return 0.0
        # A signed fraction reaches the limit on whichever side it points, so
        # the two directions are the same control rather than two primitives.
        return float(fraction) * (high if fraction > 0 else -low)

    quaternion = compose(
        DofAngles(
            math.radians(angle("flexion", flex_fraction)),
            math.radians(angle("abduction", sweep_fraction)),
            0.0,
        ),
        frame,
    )
    return Quat(x=quaternion[0], y=quaternion[1],
                z=quaternion[2], w=quaternion[3])


def _digit_curl(digit: str):
    """Curl one digit in, or straighten it out.

    Signed: +1 is fully curled, -1 fully extended, 0 is straight. One control
    per digit per axis, rather than a separate primitive for each direction and
    each segment -- the thumb alone had nine, which is nine menu entries and
    nine ways to pick the one that moves the wrong number.
    """

    def solve(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
        reach = float(np.clip(amount, -1.0, 1.0))
        out: dict[str, Any] = {}
        for bone, share in zip(_digit_bones(hand, digit), _CURL_SHARE):
            rotation = _digit_rotation(bone, reach * share, 0.0)
            if rotation is not None:
                out[bone] = rotation
        return out

    return solve


def _digit_sweep(digit: str):
    """Swing one digit sideways, tracing a horizontal line.

    Signed, and applied at the base joint only, because that is where a digit
    swings from -- sweeping at the tip bends it rather than moving it across.
    """

    def solve(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
        # Swinging a digit sideways out of a grasp is a release. In run 000507
        # the hand had the block at 11.6 N on the thumb against two fingers, was
        # lifting it correctly, and swept the thumb on the next decision -- the
        # block was 10 cm away before the following one.
        if holding_object(sensing):
            return {}
        reach = float(np.clip(amount, -1.0, 1.0))
        base = _digit_bones(hand, digit)[0]
        rotation = _digit_rotation(base, 0.0, reach)
        return {base: rotation} if rotation is not None else {}

    return solve


#: Contact force at which a digit has arrived and stops being driven inward,
#: newtons. Low, because the job of closing is to MAKE contact, not to crush:
#: the squeeze that holds the object is a separate act with a separate purpose,
#: and conflating the two is how a finger ends up inside what it is holding.
_SETTLED_FORCE_N = 0.8

#: The firmest squeeze a full-amplitude close will hold, newtons. Enough to
#: carry a graspable object against gravity with margin, not enough to crush it.
_SQUEEZE_FORCE_N = 6.0

#: Thumb force below which a lift becomes a squeeze instead, newtons.
#: A 0.25 kg block needs about m*g / (2*mu) = 1.5 N per side to hold at
#: rest; carrying it while the arm accelerates needs several times that,
#: and 5.6 N was measured dropping it.
_CARRY_FORCE_N = 8.0

#: Slack left above the object's width when closing, metres.
_GRIP_FLOOR_MARGIN_M = 0.012

#: How far off the grasp line the object may be and still be worth closing
#: on, metres. Beyond this the digits are beside it rather than around it.
_CLOSE_MAX_OFFSET_M = 0.038


def _hold_force_n(amount: float) -> float:
    """What force this close is trying to reach, given how firmly it was asked."""
    reach = float(np.clip(amount, 0.0, 1.0))
    return _SETTLED_FORCE_N + (_SQUEEZE_FORCE_N - _SETTLED_FORCE_N) * reach

#: How much wider than the object the open grip stands, metres. Room for the
#: object to enter without the digits having to be driven through it, and no
#: more: a hand opened wider than it needs is a hand that cannot reach what it
#: is holding by the time it has closed as far as it can.
_GRIP_CLEARANCE_M = 0.035

#: The four fingers, in the order they sit across the hand.
_FINGERS = ("index", "middle", "ring", "little")


def grip_rays(bones: dict[str, BonePose], hand: Hand) -> dict[str, Any] | None:
    """The thumb and the finger group, each as a tip, a base and a direction."""
    side = hand.value
    try:
        positions = rig_kinematics().canonical_positions(bones)
    except Exception:  # noqa: BLE001
        return None

    def ray(tip_bone: str, base_bone: str):
        tip, base = positions.get(tip_bone), positions.get(base_bone)
        if tip is None or base is None:
            return None
        tip = np.asarray(tip, dtype=float)
        base = np.asarray(base, dtype=float)
        span = tip - base
        size = float(np.linalg.norm(span))
        if size < 1e-9:
            return None
        return tip, base, span / size

    # One joint back from the tip, not the knuckle. A bone's own rotation does
    # not move its own origin, so a base taken at the metacarpal and the
    # knuckles cannot be moved by any digit control -- measured, it read 9.06 cm
    # at every pose in the search, which is a constant wearing a metric's name.
    thumb = ray(f"{side}ThumbDistal", f"{side}ThumbProximal")
    fingers = [
        ray(f"{side}{digit.title()}Distal", f"{side}{digit.title()}Intermediate")
        for digit in _FINGERS
    ]
    fingers = [f for f in fingers if f is not None]
    if thumb is None or not fingers:
        return None
    tips = np.mean([f[0] for f in fingers], axis=0)
    bases = np.mean([f[1] for f in fingers], axis=0)
    direction = np.mean([f[2] for f in fingers], axis=0)
    size = float(np.linalg.norm(direction))
    if size < 1e-9:
        return None
    return {
        "thumb_tip": thumb[0], "thumb_base": thumb[1], "thumb_dir": thumb[2],
        "finger_tip": tips, "finger_base": bases, "finger_dir": direction / size,
    }


def holding_object(sensing: Sensing, threshold_n: float = 0.5) -> bool:
    """Is the hand carrying the object right now?

    Opposing contact: the thumb loaded against at least one finger. This is the
    goal state, and it is fragile -- any control that opens the hand while it is
    true is a release, whatever it was chosen for.
    """
    if sensing.contact_force_n.get("thumb", 0.0) < threshold_n:
        return False
    return any(
        sensing.contact_force_n.get(digit, 0.0) >= threshold_n
        for digit in _FINGERS
    )


def grip_parallel(sensing: Sensing, hand: Hand) -> float:
    """+1 when the thumb and the finger group point the SAME way.

    Not at each other. An open grip -- the shape a hand takes just before it
    closes on something -- has the thumb and the fingers both pointing out away
    from the palm, roughly parallel, with the object destined for the gap
    between them. Aiming them at each other describes a hand that has already
    closed, which is why the old measure could only come alive below a 4.4 cm
    opening while the block it had to admit was 6.0 cm wide.
    """
    rays = grip_rays(sensing.bones, hand)
    if rays is None:
        return 0.0
    return float(np.dot(rays["thumb_dir"], rays["finger_dir"]))


def grip_tip_spread_m(sensing: Sensing, hand: Hand) -> float:
    """The opening: thumb tip to the middle of the fingertips, metres.

    Opened as wide as it will go while the digits stay parallel; closed, later,
    with every finger's curl held fixed. One number, two phases.
    """
    rays = grip_rays(sensing.bones, hand)
    if rays is None:
        return 0.0
    return float(np.linalg.norm(rays["thumb_tip"] - rays["finger_tip"]))


def grip_base_spread_m(sensing: Sensing, hand: Hand) -> float:
    """Thumb knuckle to the middle of the finger knuckles, metres.

    What stops a blade from passing as a grip. A flat hand can hold its thumb
    and fingers parallel and its tips apart while every base sits in the same
    plane, and that hand encloses nothing. Forcing the bases apart as well is
    what makes the shape a C rather than a fan.
    """
    rays = grip_rays(sensing.bones, hand)
    if rays is None:
        return 0.0
    return float(np.linalg.norm(rays["thumb_base"] - rays["finger_base"]))


def _solve_open_grip(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Open the hand into a C: digits parallel, tips and bases spread wide.

    Searched rather than authored, over each digit's own two controls, because
    the pose that maximises this is a property of the rig and not something to
    guess at. Scored as parallelism plus both separations, which is exactly the
    shape the definition describes and nothing else.
    """
    # Opening a hand that is holding something is how you put it down. Run
    # 000503 opened twice while carrying the block and spent the rest of the run
    # chasing it across the table.
    if holding_object(sensing):
        return {}
    reach = float(np.clip(amount, 0.0, 1.0))
    best: tuple[float, dict[str, Any]] | None = None
    for thumb_curl in (-1.0, -0.4, 0.2):
        for thumb_sweep in (-1.0, -0.4, 0.2, 0.8):
            for finger_curl in (-0.4, 0.1, 0.6):
                for finger_sweep in (-0.4, 0.2):
                    rotations: dict[str, Any] = {}
                    rotations.update(_digit_curl("thumb")(
                        sensing, hand, thumb_curl * reach))
                    rotations.update(_digit_sweep("thumb")(
                        sensing, hand, thumb_sweep * reach))
                    for digit in _FINGERS:
                        rotations.update(_digit_curl(digit)(
                            sensing, hand, finger_curl * reach))
                        rotations.update(_digit_sweep(digit)(
                            sensing, hand, finger_sweep * reach))
                    trial = dict(sensing.bones)
                    for bone, rotation in rotations.items():
                        trial[bone] = BonePose(rotation=rotation)
                    probe = Sensing(
                        bones=trial, object_position=sensing.object_position,
                        tip_positions=sensing.tip_positions,
                        convergence=sensing.convergence, contact_force_n={},
                        opposed=False, time_s=sensing.time_s,
                        object_half_m=sensing.object_half_m)
                    # Sized to the OBJECT, not maximal. "As wide as possible"
                    # gave a 16 cm opening with the fingers straight, around a
                    # 6 cm block: the digits straddled far wider than the thing
                    # they were meant to hold, their pads faced outward, and
                    # closing bottomed out at 12.7 cm with the thumb never once
                    # touching it. An opening is only useful at the object's
                    # size, and the fingers have to be curled enough that their
                    # PADS face the gap rather than the room.
                    #
                    # Base spread stays maximal: that is the depth of the C, and
                    # it is what a blade cannot fake.
                    span = float(np.max(sensing.object_half_m) * 2.0)
                    wanted = span + _GRIP_CLEARANCE_M
                    score = (
                        grip_parallel(probe, hand) * 2.0
                        - abs(grip_tip_spread_m(probe, hand) - wanted) * 12.0
                        + grip_base_spread_m(probe, hand) * 4.0
                    )
                    if best is None or score > best[0]:
                        best = (score, rotations)
    # Doing nothing is a candidate. Every pose above is built from the rest
    # pose, so without this the search cannot choose to KEEP a hand that is
    # already open wider than anything it can construct.
    span = float(np.max(sensing.object_half_m) * 2.0)
    wanted = span + _GRIP_CLEARANCE_M
    here = (
        grip_parallel(sensing, hand) * 2.0
        - abs(grip_tip_spread_m(sensing, hand) - wanted) * 12.0
        + grip_base_spread_m(sensing, hand) * 4.0
    )
    if best is None or here >= best[0]:
        return {}
    return best[1]


def _solve_close_grip(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Close the opening with every finger's curl LOCKED.

    Only the base joint of each digit moves. Whatever shape the fingers were
    opened into is the shape they keep, so the tips come together by the grip
    closing rather than by fingertips curling inward to meet in mid-air with the
    object outside them.

    The step is absolute and clamped to the joint's own range, not composed onto
    whatever the digit is currently holding. Composing looked equivalent and was
    not: with the rate limiter lagging behind, each frame added another delta to
    a pose that had not finished applying the last one, and the wind-up rolled
    the digits past their limits -- measured, the opening ballooned from 8 cm to
    19 and the digits came out ANTI-parallel at -0.59, which is a hand turning
    itself inside out while nominally closing.

    A digit already carrying load is left alone, so the ones still in the air
    keep coming. That is what lets a hand settle onto a shape rather than
    driving its first contact through the object.
    """
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose, decompose
    from .analysis.anatomy.rom import rom_limit
    from .models import Quat

    reach = float(np.clip(amount, 0.0, 1.0))
    frames = all_frames()
    # A grip cannot be narrower than the thing it holds. Force alone does not
    # say so: the digits were still reading 1-2 N against a 6 N target, so they
    # kept closing, went to 4.86 cm around a 6.0 cm block, and squeezed it out
    # sideways -- the object escapes rather than the force rising. Solids do not
    # compress, and the geometry has to say what the force cannot.
    # Plus a margin, for two reasons. Five digits each pass their own check
    # while their COMBINED motion overshoots, and the rate limiter means the
    # commanded pose runs ahead of the pose the body has actually reached -- so
    # by the time the hand catches up it is already inside where the object was.
    # Measured without the margin: 5.13 cm of opening around a 6.0 cm block.
    # Closing on an object that is not between the digits can only push it, so
    # the hand declines rather than doing it. This is the same refusal move_to
    # makes on contact, and it is needed for the same reason: no actuator should
    # be commanded a motion whose only possible effect is to make things worse.
    #
    # Told this as a threshold in the prompt instead, the model stopped closing
    # altogether and pushed the block 48 cm without ever shutting its hand; told
    # nothing, it closed at 5.3 cm of offset and shoved the block 12 cm in three
    # tenths of a second. A rule the body keeps needs no discipline from the
    # thing deciding, and the refusal is reported, so it reads as "move first",
    # not as silence.
    if object_in_grasp(sensing, hand) > _CLOSE_MAX_OFFSET_M:
        return {}

    floor = float(np.min(sensing.object_half_m) * 2.0) + _GRIP_FLOOR_MARGIN_M
    if grip_tip_spread_m(sensing, hand) <= floor:
        return {}
    out: dict[str, Any] = {}
    for digit in ("thumb",) + _FINGERS:
        # The force a digit stops at rises with the amplitude asked for, so one
        # control covers both jobs: a light close ARRIVES on the object, and a
        # firm one SQUEEZES it hard enough to carry.
        #
        # The distinction is not cosmetic. Arriving needs almost no force and
        # too much of it drives a finger through what it is touching; carrying
        # needs enough friction to beat the object's weight, which for a 0.25 kg
        # block at mu 0.8 is about m*g / (2*mu) = 1.5 N per side before any
        # margin. A grip settled at 0.8 N is a grip that lets go the moment the
        # arm moves -- measured, exactly that: pairs formed at 1.4 s, the lift
        # began, and the block stayed on the table.
        if sensing.contact_force_n.get(digit, 0.0) >= _hold_force_n(amount):
            continue
        base = _digit_bones(hand, digit)[0]
        frame = frames.get(base)
        if frame is None:
            continue
        held = sensing.bones.get(base)
        if held is None:
            angles = DofAngles(0.0, 0.0, 0.0)
        else:
            try:
                angles = decompose(
                    [held.rotation.x, held.rotation.y,
                     held.rotation.z, held.rotation.w], frame)
            except Exception:  # noqa: BLE001
                angles = DofAngles(0.0, 0.0, 0.0)
        # The thumb closes by ADDUCTION across the palm, not by flexion. The
        # range-of-motion manifest has said so all along -- it records that the
        # thumb is the one chain where the authored asset and the anatomical
        # frame disagree, and that the rig's own crate_grip preset closes it by
        # adduction. Closed on its flexion axis it curled without ever crossing
        # toward the fingers: index and middle would settle at 1 N while the
        # thumb sat 5 cm off the block and the opening stopped shrinking.
        dof = "abduction" if digit == "thumb" else "flexion"
        try:
            low, high = rom_limit(base, dof).typical_deg
        except Exception:  # noqa: BLE001
            low, high = -60.0, 60.0
        here = float(np.degrees(
            angles.abduction_rad if dof == "abduction" else angles.flexion_rad))

        def toward(edge: float) -> float:
            step = reach * (edge - here) * 0.35
            return float(np.clip(here + step, min(low, high), max(low, high)))

        # Which way is "across the palm" is a fact about the rig, so it is
        # measured rather than assumed: whichever end of the range brings the
        # tips together is the closing direction.
        best_target, best_spread = here, None
        for edge in (high, low):
            candidate = toward(edge)
            angle_set = (
                DofAngles(angles.flexion_rad, math.radians(candidate),
                          angles.twist_rad)
                if dof == "abduction" else
                DofAngles(math.radians(candidate), angles.abduction_rad,
                          angles.twist_rad)
            )
            probe_q = compose(angle_set, frame)
            trial = dict(sensing.bones)
            trial[base] = BonePose(rotation=Quat(
                x=probe_q[0], y=probe_q[1], z=probe_q[2], w=probe_q[3]))
            probe = Sensing(
                bones=trial, object_position=sensing.object_position,
                tip_positions=sensing.tip_positions,
                convergence=sensing.convergence, contact_force_n={},
                opposed=False, time_s=sensing.time_s,
                object_half_m=sensing.object_half_m)
            spread = grip_tip_spread_m(probe, hand)
            # Never past the object's own width. Checking only before the step
            # let a single frame jump the floor -- 7.90 cm to 5.55 around a
            # 6.0 cm block -- and once the digits are inside where the object
            # is, it has already been squeezed out.
            if spread < floor:
                continue
            if best_spread is None or spread < best_spread:
                best_spread, best_target = spread, candidate
        target = best_target
        quaternion = compose(
            DofAngles(angles.flexion_rad, math.radians(target), angles.twist_rad)
            if dof == "abduction" else
            DofAngles(math.radians(target), angles.abduction_rad, angles.twist_rad),
            frame,
        )
        out[base] = Quat(x=quaternion[0], y=quaternion[1],
                         z=quaternion[2], w=quaternion[3])
    return out

def _solve_grip(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Close every finger's C on the object. This IS the grip.

    Searched over the thumb and the finger curls together, scored by the mean C
    across all four fingers rather than by curl. Curling was never the thing:
    a hand can curl hard with its digits pointing past each other and produce a
    push, which is what every closing action here has done.
    """
    from .force_closure import digit_rotations

    reach = float(np.clip(amount, 0.0, 1.0))
    best: tuple[float, dict[str, Any]] | None = None
    for finger_curl in np.linspace(0.2, 0.95, 6):
        for thumb_curl in np.linspace(0.2, 0.95, 6):
            for oppose in (0.2, 0.45, 0.7):
                rotations = digit_rotations(
                    hand,
                    {"thumb": float(thumb_curl * reach + 0.1),
                     **{d: float(finger_curl * reach + 0.1) for d in
                        ("index", "middle", "ring", "little")}},
                    opposition=float(oppose),
                )
                trial = dict(sensing.bones)
                for bone, rotation in rotations.items():
                    trial[bone] = BonePose(rotation=rotation)
                # Lower is better: -1 is every finger closed in a C.
                score = grip_closure(trial, hand)
                if best is None or score < best[0]:
                    best = (score, rotations)
    return best[1] if best is not None else {}


def _solve_close(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Close the hand, thumb coming across as it does.

    ``oppose_thumb`` used to be a separate action and it should not have been.
    Closing a hand IS the thumb travelling to meet the fingers; splitting them
    gave the selector two controls that each undid the other's work, and it
    spent whole stages alternating between them -- opposition flattening the
    aperture, closing restoring it, neither ever reaching the object.

    One action now, with the thumb's opposition rising alongside the curl and
    capped where the aperture is still standing. Measured, the angle holds
    between 56 and 68 degrees across the whole range instead of collapsing to
    19 at the top of it.
    """
    reach = float(np.clip(amount, 0.0, 1.0))
    return _solve_digits(
        hand,
        curl=0.15 + 0.55 * reach,
        opposition=0.25 + 0.35 * reach,
    )


def _solve_oppose(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Carry the thumb across the palm toward the fingers it works against.

    The one coordination every grasp in this project has failed on: contacts
    exist in quantity -- the palm has pressed this block at 50 N -- but never on
    two opposing faces, so friction has nothing to work against and the object
    slides instead of lifting.
    """
    from .force_closure import digit_rotations

    # Opposition is CAPPED, and that cap is the whole fix. Driven to 1.2 this
    # primitive flattened the aperture it was supposed to be closing across --
    # measured, the angle falls from 68 degrees at opposition 0.3 to 19 at 1.2 --
    # so it and ``open_hand`` spent a whole stage undoing each other, the model
    # alternating between them and correctly narrating the trap: "the aperture
    # is flat to the palm, so bring the thumb across to square the grasp".
    #
    # The thumb reaches across on CURL, which leaves the aperture standing. Past
    # about 0.6 of opposition there is nothing left to oppose into.
    return digit_rotations(
        hand,
        {"thumb": 0.15 + 0.45 * float(np.clip(amount, 0.0, 1.0)),
         "index": 0.55, "middle": 0.55, "ring": 0.55, "little": 0.55},
        opposition=0.25 + 0.35 * float(np.clip(amount, 0.0, 1.0)))


#: A candidate must bring the thumb at least this much closer to the fingers to
#: count as inward. Small, so a near-stationary refinement still qualifies.
_INWARD_EPSILON_M = 0.0005


def c_shape(
    bones: dict[str, BonePose], hand: Hand, finger: str = "index"
) -> dict[str, float]:
    """Do the thumb and index form a closed C, measured as two rays.

    Take each fingertip and extend it along its last bone. For a C the two rays
    must CONVERGE -- each pointing at the other -- and pass close enough to be
    one loop. Two rays that leave the tips at right angles and never meet are
    not a small C, they are a pair of blades, however near the tips happen to be.

    Returns the closing distance between the rays, whether each points toward
    the other, and how far from coplanar they are. The earlier measure only
    asked which way the thumb PAD faced, which a hand can satisfy while its
    fingers point past each other and enclose nothing.
    """
    side = hand.value
    kinematics = rig_kinematics()
    try:
        positions = kinematics.canonical_positions(bones)
    except Exception:  # noqa: BLE001
        return {"gap_m": 1.0, "converging": 0.0, "coplanar_m": 1.0}

    def ray(distal: str, proximal: str) -> tuple[np.ndarray, np.ndarray] | None:
        tip, base = positions.get(distal), positions.get(proximal)
        if tip is None or base is None:
            return None
        direction = np.asarray(tip, dtype=float) - np.asarray(base, dtype=float)
        size = float(np.linalg.norm(direction))
        if size < 1e-9:
            return None
        return np.asarray(tip, dtype=float), direction / size

    thumb = ray(f"{side}ThumbDistal", f"{side}ThumbProximal")
    stem = finger.title()
    index = ray(f"{side}{stem}Distal", f"{side}{stem}Intermediate")
    if thumb is None or index is None:
        return {"gap_m": 1.0, "converging": 0.0, "coplanar_m": 1.0}

    (p1, d1), (p2, d2) = thumb, index
    between = p2 - p1
    span = float(np.linalg.norm(between))
    if span < 1e-9:
        return {"gap_m": 0.0, "converging": 1.0, "coplanar_m": 0.0}
    unit = between / span

    # THE dot product of the two rays. Two unit vectors that are parallel and
    # opposite give -1, which is a thumb and finger aimed straight at each
    # other: a C. At 0 they are perpendicular, which is the pair of blades that
    # cannot enclose anything. At +1 they point the same way.
    #
    # Measured against the line BETWEEN the tips instead, as this was before, a
    # hand scores well for having its tips near each other while the fingers
    # themselves point past each other -- which is exactly the shape that kept
    # failing.
    facing = float(np.dot(d1, d2))
    # Reported as "how close to -1", so higher is better like everything else.
    converging = -facing

    # Do the rays point AT each other, or away? Antiparallel is both: a thumb
    # and finger aimed at one another give -1, and so does a hand splayed wide
    # with the two pointing back to back. Told to make the dot product -1, the
    # search found the second -- the hand opened flat, the metric was satisfied,
    # and nothing could be held. Direction alone cannot tell a C from a fan.
    toward_each_other = min(float(np.dot(d1, unit)), float(np.dot(d2, -unit)))

    # Closest approach between the two infinite lines: how nearly they meet.
    cross = np.cross(d1, d2)
    size = float(np.linalg.norm(cross))
    if size < 1e-9:
        gap = float(np.linalg.norm(np.cross(between, d1)))
    else:
        gap = abs(float(np.dot(between, cross / size)))
    return {
        # How far the two rays miss each other by. Zero is a closed loop.
        "gap_m": gap,
        # The raw dot product of the two ray directions. -1 is antiparallel,
        # which is necessary for a C and not sufficient.
        "ray_dot": facing,
        # +1 when each ray points at the other's tip, negative when they point
        # away. This is what separates a closing C from an opening fan.
        "toward": toward_each_other,
        # The honest single number: antiparallel AND closing. Reported as the
        # dot product when the rays converge, and as +1 -- the worst case, a
        # blade -- when they do not, so that targeting -1 cannot be met by
        # opening the hand.
        "c_closure": facing if toward_each_other > 0.0 else 1.0,
        # The same thing sign-flipped, so +1 is best.
        "converging": converging,
        # Out-of-plane separation, which is the same quantity here.
        "coplanar_m": gap,
    }



def digits_straddle(sensing: Sensing, hand: Hand) -> float:
    """Are the thumb and fingers on opposite SIDES of the object, or stacked?

    +1 when the line from thumb tip to fingertip runs parallel to the surface
    the object rests on -- the two digits level with each other, with the object
    able to sit between them. 0 when that line is vertical: both digits on the
    same face, one above the other, which is the arrangement every failed run
    has been in. In 000489 the thumb rode 7.6 cm above the block while the index
    sat level with its middle, and nothing measured it.

    This is the wrist's number. It is deliberately separate from the C measures,
    because the two describe different halves of a grasp and only the pair is
    sufficient: this one says the digits are on opposite sides of the object,
    and c_closure says they have closed on it. Swept through the wrist's whole
    range, c_closure does not move by a thousandth -- turning the wrist carries
    thumb and fingers together -- so a single number could never have driven
    both, and the half without a number was the half that never happened.
    """
    side = hand.value
    try:
        positions = rig_kinematics().canonical_positions(sensing.bones)
    except Exception:  # noqa: BLE001
        return 0.0
    thumb = positions.get(f"{side}ThumbDistal")
    finger = positions.get(f"{side}IndexDistal")
    if thumb is None or finger is None:
        return 0.0
    span = np.asarray(finger, dtype=float) - np.asarray(thumb, dtype=float)
    size = float(np.linalg.norm(span))
    if size < 1e-9:
        return 0.0
    return 1.0 - abs(float(np.dot(span / size, np.asarray([0.0, 1.0, 0.0]))))


def grip_closure(bones: dict[str, BonePose], hand: Hand) -> float:
    """The mean C across ALL four fingers. -1 is a whole hand closed on something.

    A grip is not one C. Each finger forms its own with the thumb, and closing
    all four IS gripping -- there is no separate squeezing step, which is why
    "close the hand" as a distinct action kept undoing whatever shape had just
    been made. Measured on the index alone, three fingers can be anywhere.
    """
    values = [
        c_shape(bones, hand, finger)["c_closure"]
        for finger in ("index", "middle", "ring", "little")
    ]
    return float(np.mean(values)) if values else 1.0


def object_in_grasp(sensing: Sensing, hand: Hand) -> float:
    """Distance from the object to the line between thumb and finger group.

    Near zero means the object sits INSIDE the opening, between the thumb and
    the fingers, which is where it has to be before closing can hold it. The
    approach was aiming the fingertips a fixed distance from the object's centre
    and stopping there, which leaves the object beside the hand rather than in
    it -- the hand then tries to grip a thing that is not between its digits.
    """
    thumb = sensing.tip_positions.get("thumb")
    fingers = [
        sensing.tip_positions[d]
        for d in ("index", "middle", "ring", "little")
        if d in sensing.tip_positions
    ]
    if thumb is None or not fingers:
        return 1.0
    other = np.mean(fingers, axis=0)
    span = other - thumb
    length = float(np.linalg.norm(span))
    if length < 1e-9:
        return float(np.linalg.norm(sensing.object_position - thumb))
    unit = span / length
    along = float(np.dot(sensing.object_position - thumb, unit))
    # Clamped, so an object beyond either tip is measured from that tip.
    along = float(np.clip(along, 0.0, length))
    closest = thumb + unit * along
    return float(np.linalg.norm(sensing.object_position - closest))


def thumb_pad_facing(bones: dict[str, BonePose], hand: Hand) -> float:
    """Which way the thumb PAD points. +1 toward the fingers, 0 sideways.

    The difference between a C and a blade, and the quantity that decides
    whether a thumb can press anything. A thumb can have its tip exactly where a
    grasp needs it and still be turned so the pad faces out of the hand -- the
    tip arrives, there is no face to press with, and no amount of closing
    produces force.

    It was missing from the opposition ladder because that was fitted by
    minimising thumb-tip to fingertip DISTANCE, which a blade satisfies as well
    as a C. Measured afterwards, ``oppose_middle`` and ``oppose_ring`` -- the
    two a mid-hand grasp naturally selects -- put the pad at 0.015 and 0.098.
    """
    side = hand.value
    kinematics = rig_kinematics()
    try:
        rotation = kinematics.canonical_world_rotation(bones, f"{side}ThumbDistal")
        positions = kinematics.canonical_positions(bones)
    except Exception:  # noqa: BLE001
        return 0.0
    pad = rotation @ np.asarray([-1.0, 0.0, 0.0])
    fingers = np.mean(
        [positions[f"{side}{d}Distal"] for d in ("Index", "Middle", "Ring", "Little")],
        axis=0,
    )
    toward = fingers - positions[f"{side}ThumbDistal"]
    size = float(np.linalg.norm(toward))
    return float(np.dot(pad, toward / size)) if size > 1e-9 else 0.0


def _thumb_to_fingers(sensing: Sensing) -> float:
    """Distance from the thumb tip to the middle of the finger group.

    The quantity that says whether the thumb is coming in or going out. Grabbing
    reduces it; releasing raises it.
    """
    thumb = sensing.tip_positions.get("thumb")
    fingers = [
        sensing.tip_positions[d]
        for d in ("index", "middle", "ring", "little")
        if d in sensing.tip_positions
    ]
    if thumb is None or not fingers:
        return float("inf")
    return float(np.linalg.norm(thumb - np.mean(fingers, axis=0)))


def thumb_opposition_score(sensing: Sensing, hand: Hand | None = None) -> float:
    """How well placed the thumb is to form a pair. 1.0 is directly opposite.

    A pair is the thumb and a finger loaded on OPPOSITE faces, so the geometry
    that decides it is which side of the object each is on -- not how close
    either is. Measured as the angle between the thumb and the nearest finger
    as seen from the object's centre: directly across is +1, alongside is 0,
    same side is -1.

    Nothing measured this before, and that is why the pair goals could not be
    worked toward. Their error was contact distance plus a constant penalty for
    having no pairs, so before anything touched, a thumb tucked beside the
    fingers scored exactly as well as one placed across from them. The goal
    could not tell the two apart, so no action could move it and every run
    ended with pairs at zero.
    """
    thumb = sensing.tip_positions.get("thumb")
    if thumb is None:
        return -1.0
    centre = sensing.object_position
    to_thumb = thumb - centre
    size = float(np.linalg.norm(to_thumb))
    if size < 1e-9:
        return -1.0
    to_thumb = to_thumb / size
    best = -1.0
    for digit in ("index", "middle", "ring", "little"):
        tip = sensing.tip_positions.get(digit)
        if tip is None:
            continue
        to_finger = tip - centre
        length = float(np.linalg.norm(to_finger))
        if length < 1e-9:
            continue
        # -1 when they point the same way from the centre, +1 when opposite.
        best = max(best, -float(np.dot(to_thumb, to_finger / length)))
    return best


def _thumb_dof_candidates(hand: Hand, reach: float) -> list[dict[str, Any]]:
    """Thumb poses swept over its own flexion, abduction and twist."""
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose
    from .analysis.anatomy.rom import rom_limit
    from .models import Quat

    bone = f"{hand.value}ThumbMetacarpal"
    frames = all_frames()
    spans = {
        dof: rom_limit(bone, dof).typical_deg for dof in ("flexion", "abduction", "twist")
    }
    out: list[dict[str, Any]] = []
    grid = np.linspace(-1.0, 1.0, 5)
    for flex in grid:
        for abduct in grid:
            for twist in grid:
                angles = {}
                for dof, value in (("flexion", flex), ("abduction", abduct),
                                   ("twist", twist)):
                    low, high = spans[dof]
                    angles[dof] = value * (high if value >= 0 else -low) * reach
                xyzw = compose(
                    DofAngles(
                        flexion_rad=math.radians(angles["flexion"]),
                        abduction_rad=math.radians(angles["abduction"]),
                        twist_rad=math.radians(angles["twist"]),
                    ),
                    frames[bone],
                )
                out.append({bone: Quat(
                    x=float(xyzw[0]), y=float(xyzw[1]),
                    z=float(xyzw[2]), w=float(xyzw[3]))})
    return out


def _solve_place_thumb(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Bring the thumb inward across the palm, toward the finger it must oppose.

    This is the motion a hand makes touching thumb to little finger: the thumb
    travels ACROSS the palm rather than curling in front of it, and it is what
    makes a grip possible at all. The vocabulary already holds it -- the
    opposition ladder in ``config/body_parts.v1.json``, fitted by search against
    this rig rather than authored:

        oppose_index    abduction -0.33   nearest the index
        oppose_middle   abduction -0.50
        oppose_ring     abduction -0.67
        oppose_little   abduction -1.00   furthest across
        palmar_adduct                     laid against the palm, four fingers up

    Abduction is the axis that chooses which finger, which is the anatomy: written
    from a sign convention first, every one of these carried the thumb AWAY from
    the fingers, 17.0 cm at oppose_little against 10.4 for a plain extend.

    Searched here over which finger to oppose and how far to travel, scored by
    whether the thumb ends up across the object from the fingers. The previous
    version drove generic curl and opposition parameters and never used the
    fitted motion at all.
    """
    from .body_parts import move_rotations

    part = f"{hand.value}_thumb"
    reach = float(np.clip(amount, 0.0, 1.0))
    here = _thumb_to_fingers(sensing)
    best: tuple[float, dict[str, Any]] | None = None
    candidates: list[dict[str, Any]] = []
    for move in ("oppose_index", "oppose_middle", "oppose_ring",
                 "oppose_little", "palmar_adduct"):
        for magnitude in (0.4, 0.7, 1.0):
            try:
                candidates.append(move_rotations(part, move, magnitude * reach))
            except Exception:  # noqa: BLE001
                continue
    # The named poses are five points in a three-dimensional space and none of
    # them was chosen for pad orientation. Searching the DOFs directly lets a C
    # be found where the ladder only offers blades.
    candidates.extend(_thumb_dof_candidates(hand, reach))
    for rotations in candidates:
        if True:
            trial = dict(sensing.bones)
            for bone, rotation in rotations.items():
                trial[bone] = BonePose(rotation=rotation)
            probe = sense(
                trial, hand, sensing.object_position,
                sensing.contact_force_n, sensing.opposed, sensing.time_s,
            )
            tip = probe.tip_positions.get("thumb")
            if tip is None:
                continue
            # INWARD ONLY. Grabbing has a direction: the thumb travels toward
            # the fingers it will work against, and a candidate that carries it
            # the other way is not a worse grasp, it is the opposite motion.
            # Scored rather than constrained, the search took poses that opened
            # the hand out at the very moment it should have been closing --
            # visible on screen as the thumb swinging away just as the fingers
            # arrived.
            if _thumb_to_fingers(probe) > here - _INWARD_EPSILON_M:
                continue
            across = thumb_opposition_score(probe)
            near = -abs(float(np.linalg.norm(tip - sensing.object_position)))
            # A C, not a blade. Weighted to dominate, because a thumb whose pad
            # faces out of the hand cannot press however well placed its tip is,
            # and placement alone is what the ladder was fitted for.
            shape = c_shape(trial, hand)
            # Close the loop: rays converging and nearly meeting.
            score = (
                2.0 * shape["converging"] - 4.0 * shape["gap_m"] + across + 0.5 * near
            )
            if best is None or score > best[0]:
                best = (score, rotations)
    return best[1] if best is not None else {}


def _solve_orient_palm(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Supinate the forearm until the palm faces the object.

    The DOF this needed all along, and it was frozen. Measured across a run,
    ``rightLowerArm`` twist held at exactly -0.0 for every frame, on every clip:
    the reach solver never writes it, and the closed loop passed neutral
    parameters, so nothing else did either. The hand was carried around like a
    fixed block on the end of a working arm.

    Turning it is the whole difference between a graspable presentation and an
    impossible one::

        forearm twist   -60 deg -> palm faces straight AWAY   (-1.00)
                          0 deg -> where every run sat        (-0.49)
                        +80 deg -> palm faces the object      (+0.87)

    An earlier version of this searched the WRIST bone instead, which carries
    only 10 degrees of roll against the forearm's 80, and moved the hand more
    than it turned it. Supination is a forearm act; the wrist deviates and
    flexes but it does not turn the palm over.
    """
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose
    from .analysis.anatomy.rom import rom_limit
    from .grasp_aperture import _palm_normal
    from .models import Quat

    bone = f"{hand.value}LowerArm"
    toward = sensing.object_position - sensing.convergence
    distance = float(np.linalg.norm(toward))
    if distance < 1e-6:
        return {}
    toward = toward / distance

    frames = all_frames()
    low, high = rom_limit(bone, "twist").typical_deg
    existing = sensing.bones.get(bone)
    # Keep whatever flexion and abduction the reach solved for; only the twist
    # is ours. Overwriting the others would undo the arm's own solution.
    if existing is not None:
        from .analysis.anatomy.frame import decompose

        current = decompose(
            np.asarray([
                existing.rotation.x, existing.rotation.y,
                existing.rotation.z, existing.rotation.w,
            ]),
            frames[bone],
        )
        flexion, abduction = current.flexion_rad, current.abduction_rad
    else:
        flexion = abduction = 0.0

    best: tuple[float, Any] | None = None
    for fraction in np.linspace(-1.0, 1.0, 17):
        degrees = fraction * (high if fraction >= 0 else -low) * float(
            np.clip(amount, 0.0, 1.0)
        )
        xyzw = compose(
            DofAngles(
                flexion_rad=flexion,
                abduction_rad=abduction,
                twist_rad=math.radians(degrees),
            ),
            frames[bone],
        )
        trial = dict(sensing.bones)
        trial[bone] = BonePose(rotation=Quat(
            x=float(xyzw[0]), y=float(xyzw[1]),
            z=float(xyzw[2]), w=float(xyzw[3])))
        try:
            score = float(np.dot(_palm_normal(trial, hand.value), toward))
        except Exception:  # noqa: BLE001
            continue
        if best is None or score > best[0]:
            best = (score, trial[bone].rotation)
    return {bone: best[1]} if best is not None else {}


def _solve_lift(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Raise the hand, carrying whatever it holds."""
    from .models import PrimitiveParameters, Vec3
    from .primitives import arm_pose_from_target, shoulder_position

    positions = rig_kinematics().canonical_positions(sensing.bones)
    wrist = np.asarray(positions[f"{hand.value}Hand"], dtype=float)
    # Capped, because a lift is a rate and not a distance. The selector is
    # asked for ONE action every few tenths of a second and lift is re-solved
    # every frame in between, so a large amplitude is not "lift further", it is
    # "lift faster" -- and at full amplitude the arm is commanded 15 cm in a
    # single decision, which pulls the object straight out of the hand holding
    # it. Measured in run 000505: a grasp at 13.5 N on the thumb and 22.0 on the
    # little finger raised the block 7.45 cm and then lost it inside a second,
    # to lift@1.00.
    #
    # The cap leaves the gentle end of the range untouched, so a caller asking
    # for 0.05 gets exactly what it asked for.
    # TIGHTEN FIRST. A grip that is merely present is not a grip that carries:
    # run 000509 closed to 1.1 cm of offset -- the best approach of any run --
    # took a two-pair grasp at 5.6 N on the thumb, lifted, and lost the block
    # inside four tenths of a second. The scripted baseline squeezes to about
    # 10 N before it raises anything.
    #
    # So a lift that is asked for too early becomes a squeeze, and becomes a
    # lift by itself once the hand can hold what it is carrying. That is what a
    # person does without deciding to, and it is not a judgement worth spending
    # a decision on at this cadence.
    if sensing.contact_force_n.get("thumb", 0.0) < _CARRY_FORCE_N:
        return _solve_close_grip(sensing, hand, 1.0)

    reach = min(float(amount), 0.3)
    aim = wrist + np.asarray([0.0, reach * 0.15, 0.0])
    arm, _ = arm_pose_from_target(
        hand, shoulder_position(hand),
        Vec3(x=float(aim[0]), y=float(aim[1]), z=float(aim[2])),
        PrimitiveParameters(), present_hand=False)
    # Keep gripping while carrying. Lifting writes only the arm, so on its own
    # the digits hold a fixed pose -- and a fixed pose is not a grip: the object
    # shifts under its own weight, contact is lost, and nothing re-establishes
    # it. Measured, a grip at 2.1 N survived 1.5 s of lifting and let go; with
    # the squeeze maintained the same grip carried the block 20 cm.
    #
    # It is also not a decision to make at a model's cadence. A hand does not
    # alternate between holding and raising, and when the selector is asked for
    # ONE action every 0.7 s, anything that must be true continuously has to
    # live in the body rather than in the choice.
    return {**_solve_close_grip(sensing, hand, 1.0), **arm}



def _solve_look_at_figure(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Turn the neck and head until the object is in view."""
    from .gaze_controller import aim_gaze

    result = aim_gaze(sensing.bones, sensing.object_position)
    if amount >= 0.999:
        return dict(result.bones)
    from scipy.spatial.transform import Rotation, Slerp

    from .models import Quat

    out: dict[str, Any] = {}
    for bone, rotation in result.bones.items():
        start = sensing.bones.get(bone)
        if start is None:
            out[bone] = rotation
            continue
        a, b = start.rotation, rotation
        pair = Rotation.from_quat([[a.x, a.y, a.z, a.w], [b.x, b.y, b.z, b.w]])
        xyzw = Slerp([0.0, 1.0], pair)([float(np.clip(amount, 0.0, 1.0))]).as_quat()[0]
        out[bone] = Quat(x=float(xyzw[0]), y=float(xyzw[1]),
                         z=float(xyzw[2]), w=float(xyzw[3]))
    return out


def _solve_look_at_hand(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Watch the grasp rather than the object.

    Different from looking at the object and worth having separately: while
    closing, what matters is where the fingers are relative to the thing, and
    that is judged from the hand.
    """
    from .gaze_controller import aim_gaze

    result = aim_gaze(sensing.bones, sensing.convergence)
    return dict(result.bones)


#: The thumb posture a grasp begins from, in degrees on each bone's anatomical
#: frame: metacarpal flexion and abduction, then proximal flexion.
#:
#: Fitted, not guessed. Searched against the C measure with the index curled,
#: because the two only work together -- the same search with a straight index
#: cannot reach a C at any thumb angle, since the C measure takes the WORSE of
#: the two rays and a straight index is always the worse one:
#:
#:     index curl   best thumb        toward    ray_dot   tips apart
#:        0.0       +60 +30 +60       -0.921    -0.800     21.6 cm
#:        0.4       +30 -30 -30       +0.012    +0.824      7.6 cm
#:        0.7       +60 -30 -60       +0.537    +0.362      7.0 cm
#:        1.0       +30 -30 -60       +0.806    -0.667      1.1 cm
#:
#: The rig's neutral thumb lies alongside the hand pointing the same way as the
#: fingers, which is a hand about to karate-chop something. Every run has begun
#: from there and spent itself trying to leave: run 000489 chose a thumb move
#: twenty-two times out of twenty-six and never got the C measure off its pinned
#: value, because from a flat start the thumb is doing all the work of an
#: arrangement that takes two digits.
_THUMB_HOME_DEG = ((30.0, -30.0), (-60.0, 0.0))


def _thumb_home_rotations(hand: Hand, amount: float = 1.0) -> dict[str, Any]:
    """The opposed thumb posture, at a fraction of the way from neutral."""
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose
    from .models import Quat

    frames = all_frames()
    side = hand.value
    reach = float(np.clip(amount, 0.0, 1.0))
    (mc_flex, mc_abduct), (prox_flex, prox_abduct) = _THUMB_HOME_DEG
    plan = {
        f"{side}ThumbMetacarpal": (mc_flex, mc_abduct),
        f"{side}ThumbProximal": (prox_flex, prox_abduct),
    }
    out: dict[str, Any] = {}
    for bone, (flex, abduct) in plan.items():
        frame = frames.get(bone)
        if frame is None:
            continue
        quaternion = compose(
            DofAngles(math.radians(flex * reach), math.radians(abduct * reach), 0.0),
            frame,
        )
        out[bone] = Quat(x=quaternion[0], y=quaternion[1],
                         z=quaternion[2], w=quaternion[3])
    return out


def _solve_thumb_home(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Put the thumb where a grasp starts: across the palm, facing the fingers."""
    return _thumb_home_rotations(hand, amount)


def _solve_level_wrist(sensing: Sensing, hand: Hand, amount: float) -> dict[str, Any]:
    """Turn the hand at the wrist until thumb and fingers straddle the object.

    The waving motion, and until now the body could not make it. The wrist is
    written by reach_to, stand_off and lift, but only as a by-product of putting
    the wrist SOMEWHERE -- nothing turned it, and orient_palm drove the forearm
    instead, which is a different joint and was removed for moving nothing.

    What it fixes is a specific arrangement seen in every failed run: the thumb
    riding 7.6 cm above the block while the index sits level with its middle, so
    the two are stacked vertically on the same face rather than straddling it.
    Swept through the wrist's own range from that pose, flexing -60 with -30 of
    ulnar deviation brings both tips to the block's own height, with the line
    between them parallel to the surface it is sitting on.

    It cannot make the C, and it is worth being exact about that: the C measure
    does not move by a thousandth at ANY wrist angle, because turning the wrist
    carries the thumb and the fingers together and the C is about their
    relationship to each other. This gets them onto opposite sides. Curling
    closes them.
    """
    import math

    from .analysis.anatomy.frame import DofAngles, all_frames, compose
    from .analysis.anatomy.rom import rom_limit
    from .models import Quat

    side = hand.value
    bone = f"{side}Hand"
    frame = all_frames().get(bone)
    if frame is None:
        return {}
    kinematics = rig_kinematics()
    up = np.asarray([0.0, 1.0, 0.0])
    target_height = float(sensing.object_position[1])

    flex_low, flex_high = rom_limit(bone, "flexion").typical_deg
    abduct_low, abduct_high = rom_limit(bone, "abduction").typical_deg

    def cost(flex: float, abduct: float) -> float | None:
        quaternion = compose(
            DofAngles(math.radians(flex), math.radians(abduct), 0.0), frame)
        trial = dict(sensing.bones)
        trial[bone] = BonePose(rotation=Quat(
            x=quaternion[0], y=quaternion[1], z=quaternion[2], w=quaternion[3]))
        try:
            positions = kinematics.canonical_positions(trial)
        except Exception:  # noqa: BLE001
            return None
        thumb = positions.get(f"{side}ThumbDistal")
        finger = positions.get(f"{side}IndexDistal")
        if thumb is None or finger is None:
            return None
        span = np.asarray(finger, dtype=float) - np.asarray(thumb, dtype=float)
        size = float(np.linalg.norm(span))
        if size < 1e-9:
            return None
        # Parallel to the surface the object rests on: the two digits level with
        # each other rather than stacked.
        level = abs(float(np.dot(span / size, up)))
        # And at the object's height, not lifted clear of it. Alignment alone is
        # satisfied by a hand held 10 cm above the block with both tips level in
        # mid-air, which is tidy and grasps nothing.
        drift = (abs(float(thumb[1]) - target_height)
                 + abs(float(finger[1]) - target_height))
        return level + drift * 2.0

    here = cost(0.0, 0.0)
    best: tuple[float, float, float] | None = None
    for flex in np.linspace(flex_low, flex_high, 16):
        for abduct in np.linspace(abduct_low, abduct_high, 8):
            value = cost(float(flex), float(abduct))
            if value is None:
                continue
            if best is None or value < best[0]:
                best = (value, float(flex), float(abduct))
    if best is None or (here is not None and best[0] >= here):
        return {}
    reach = float(np.clip(amount, 0.0, 1.0))
    quaternion = compose(
        DofAngles(math.radians(best[1] * reach), math.radians(best[2] * reach), 0.0),
        frame,
    )
    return {bone: Quat(x=quaternion[0], y=quaternion[1],
                       z=quaternion[2], w=quaternion[3])}


#: Primitives kept in the code but off the menu. See the note in
#: ``_all_super_primitives`` for what each was doing and what replaced it.
RETIRED_PRIMITIVES = frozenset({
    "reach_to", "stand_off", "grip", "close_hand", "open_hand",
    "place_thumb", "thumb_home",
    # level_wrist went the way of orient_palm, for the same reason and by the
    # same route. Near the object it is in the top-four movers of no metric at
    # all, and the scripted controller never calls it once yet reaches
    # digits_straddle 0.944 anyway -- the approach and the grip produce the
    # straddle on their own. Meanwhile it was the largest single consumer of
    # decisions in the last three runs, six, three and six of twenty-two, and
    # turning the hand mid-approach moves the opening off the object it was
    # lining up on.
    "level_wrist",
})


def super_primitives(hand: Hand) -> tuple[SuperPrimitive, ...]:
    """Everything the selector may call, this frame."""
    return tuple(p for p in _all_super_primitives(hand)
                 if p.name not in RETIRED_PRIMITIVES)


def _all_super_primitives(hand: Hand) -> tuple[SuperPrimitive, ...]:
    """Every primitive that exists, retired ones included."""
    return (
        # RETIRED, and kept only as code the working primitives still call:
        #
        #   reach_to      aims the fingertips at the object's CENTRE, which is
        #                 inside it, so contact is the approach succeeding.
        #                 Superseded by move_to, which carries the palm to a
        #                 face. Measured side by side: move_to closes 10.5 cm to
        #                 5.1 monotonically and arrives square at 0.99 facing;
        #                 reach_to goes further away below 0.7 amplitude and
        #                 arrives edge-on at 0.51.
        #   stand_off     the withdrawal half of the same idea.
        #   grip,         close on the fingertips rather than on the grip, so
        #   close_hand    they meet in mid-air with the object outside them.
        #   open_hand     opens without shape; open_grip opens to the object.
        #   place_thumb,  every one of these moved thumb_opposition, which is
        #   thumb_home    contested six ways against ten, while doing nothing to
        #                 the numbers a grasp is made of. In run 000495 the
        #                 model spent nineteen of twenty-two calls among them
        #                 and never once closed the hand.
        #
        # A control that cannot help is not neutral. It reads as available, it
        # is chosen whenever the situation looks like what its name promises,
        # and it spends the decision. That has cost this project more runs than
        # any bug in the ones that work.
        SuperPrimitive("stand_off", _arm_parts(hand),
                       "bring the hand near the object without touching it",
                       _solve_stand_off),
        SuperPrimitive("move_to", _arm_parts(hand),
                       "carry the PALM to a face of the object and arrive "
                       "square to it, so the object ends up in front of the "
                       "palm rather than under the fingertips",
                       _solve_move_to),
        SuperPrimitive("reach_to", _arm_parts(hand),
                       "put the fingertips where the object is", _solve_reach),
        SuperPrimitive("open_hand", _digit_parts(hand),
                       "spread the digits wider than the object", _solve_open),
        SuperPrimitive("level_wrist", (f"{hand.value}_wrist",),
                       "turn the hand at the wrist until the thumb and the "
                       "fingers are level with each other on opposite sides of "
                       "the object, instead of stacked on the same face",
                       _solve_level_wrist),
        SuperPrimitive("thumb_home", (f"{hand.value}_thumb",),
                       "bring the thumb across the palm to where a grasp "
                       "starts, facing the fingers rather than lying alongside "
                       "them",
                       _solve_thumb_home),
        *[
            SuperPrimitive(
                f"curl_{digit}", (f"{hand.value}_{digit}",),
                f"curl the {digit} in, or straighten it out -- one control, "
                f"signed: +1 fully curled, -1 fully extended",
                _digit_curl(digit),
            )
            for digit in ("thumb", "index", "middle", "ring", "little")
        ],
        *[
            SuperPrimitive(
                f"sweep_{digit}", (f"{hand.value}_{digit}",),
                f"swing the {digit} sideways across the hand, tracing a "
                f"horizontal line -- signed, the two directions are one control",
                _digit_sweep(digit),
            )
            for digit in ("thumb", "index", "middle", "ring", "little")
        ],
        SuperPrimitive("open_grip", _digit_parts(hand),
                       "open the hand into a C -- thumb and fingers pointing "
                       "the same way, tips wide apart and knuckles wide apart, "
                       "so the object can enter the opening",
                       _solve_open_grip),
        SuperPrimitive("close_grip", _digit_parts(hand),
                       "close the opening with every finger's curl LOCKED, so "
                       "the tips come together only by the grip closing",
                       _solve_close_grip),
        SuperPrimitive("grip", _digit_parts(hand),
                       "close every finger into a C on the object -- this is "
                       "the grip itself, not a separate squeeze",
                       _solve_grip),
        SuperPrimitive("close_hand", _digit_parts(hand),
                       "curl every digit toward the object", _solve_close),
        SuperPrimitive("place_thumb", _digit_parts(hand),
                       "move the thumb across the object, opposite the fingers, "
                       "so a pair can form",
                       _solve_place_thumb),
        # orient_palm is deliberately absent. Audited against every stage goal it
        # moved none of them by any amount -- turning the forearm carries the
        # thumb and fingers together, and what these goals measure is the
        # arrangement of the digits relative to EACH OTHER, which a rotation of
        # the whole hand leaves unchanged. It was banned per stage for that
        # reason, then walked straight back in the moment the menu stopped being
        # restricted: eleven of twenty-six decisions in run 000488, each with
        # the same sentence of reasoning, while the grasp measure oscillated
        # between 3.6 and 11.4 cm and settled nowhere.
        #
        # A control that cannot move the numbers is worse than a missing one. It
        # reads as available, it is chosen whenever the situation looks like it
        # needs "better orientation", and it spends the decision. The solver is
        # kept below because the forearm twist it found is real and place_thumb
        # depends on the same anatomy; it is the offer that was wrong.
        SuperPrimitive("look_at_object", ("neck", "head"),
                       "turn the head until the object is in view",
                       _solve_look_at_figure),
        SuperPrimitive("look_at_hand", ("neck", "head"),
                       "watch the hand and what it is closing on",
                       _solve_look_at_hand),
        SuperPrimitive("lift", _arm_parts(hand),
                       "raise the hand and whatever it holds", _solve_lift),
    )


@dataclass
class SuperPrimitiveSelector:
    """Chooses a coordinated action each frame, not a pose for each part.

    Scores every super primitive at every magnitude by the error it would leave,
    and takes the best. Six actions at six magnitudes is 36 trials a frame,
    fewer than the 62 the per-part selector needed and each one a coordinated
    change rather than a single joint moved against the others' current pose.

    This is the interface a VLM implements. It sees the same :class:`Sensing`
    and returns the same choice, so the two are directly comparable and the loop
    does not know which is driving.
    """

    hand: Hand
    #: Signed, because a digit control now runs both ways: curling and
    #: extending are one primitive, and a search that only tries positive
    #: amplitudes can reach half of what the hand can do.
    magnitudes: tuple[float, ...] = (
        -1.0, -0.7, -0.4, -0.15, 0.15, 0.4, 0.7, 1.0)
    #: Controls the search may touch, empty meaning all of them plus the whole
    #: atomic layer. Set by whatever is driving -- a model that has decided this
    #: is a thumb problem, or a caller that wants an affordable run.
    shortlist: tuple[str, ...] = ()

    def choose(self, sensing: Sensing, step: Step) -> tuple[str, float, dict[str, Any]]:
        """The best action available, at either granularity.

        Super primitives are not a replacement for per-part moves, they are the
        larger of two options. Coordination is what a per-part choice cannot
        express -- reaching the block needs the shoulder, elbow and wrist
        together, and one part at a time stalls 19.9 cm out -- but plenty of
        moments want one finger adjusted rather than a whole hand re-shaped, and
        a controller that can only speak in whole actions has lost that.

        So both are scored against the same error and the better one wins. A
        super primitive earns its place each frame rather than being privileged.
        """
        here = step.error(sensing)
        best: tuple[float, str, float, dict[str, Any]] = (here, "hold", 0.0, {})

        def consider(name: str, amount: float, rotations: dict[str, Any]) -> None:
            nonlocal best
            if not rotations:
                return
            trial = dict(sensing.bones)
            for bone, rotation in rotations.items():
                trial[bone] = BonePose(rotation=rotation)
            # Probed through the eyes, not around them. Scoring a candidate with
            # `sense` left `in_view` at its default of True, so a head turn
            # never appeared to change anything and looking could not win --
            # the loop found the object once, drifted back out of view at 41
            # degrees, and spent the rest of the run acting on a memory it had
            # no reason to refresh.
            #
            # The object is placed at its BELIEVED position for the probe, which
            # is what the body has. Asking "would I see it if I turned this way"
            # about the place it thinks the object is, is reasoning it can
            # actually do; asking about the true position would be telepathy
            # again, one level up.
            probe = observe(trial, self.hand, sensing.object_position,
                            sensing.object_position, sensing.contact_force_n,
                            sensing.opposed, sensing.time_s)
            value = step.error(probe)
            if value < best[0]:
                best = (value, name, amount, rotations)

        names = tuple(self.shortlist) or tuple(step.allows)
        for name, amount, rotations in _candidates(
            sensing, self.hand, names, self.magnitudes, tuple(step.active_parts)
        ):
            consider(name, amount, rotations)

        # The atomic layer is swept only when nothing has narrowed the search.
        # It is 314 moves at six magnitudes, and scoring all of them is most of
        # what a frame costs.
        if not names:
            for part in step.active_parts:
                try:
                    available = moves_for(part)
                except Exception:
                    continue
                for move in available:
                    for amount in self.magnitudes:
                        try:
                            consider(f"{part}:{move}", amount,
                                     move_rotations(part, move, amount))
                        except Exception:
                            continue
        return best[1], best[2], best[3]


def _candidates(
    sensing: "Sensing",
    hand: Hand,
    names: tuple[str, ...],
    magnitudes: tuple[float, ...],
    parts: tuple[str, ...] = (),
):
    """Every (name, amount, rotations) the search is allowed to score.

    ``names`` is the shortlist. Empty means the whole vocabulary, which is what
    made the search cost what it does: 22 super primitives at six magnitudes is
    132 trials, but the per-part layer under them is 314 moves, and sweeping
    both is around two thousand full-body kinematics probes for every frame --
    measured at 17 seconds per decision, 270 seconds of compute per second of
    clip.

    Almost all of that is wasted. At any given moment a handful of controls
    could plausibly help and the rest are being scored to prove they do not:
    the search rediscovers, thirty times a second, that curling the little
    finger does not bring the hand closer to the block.

    Naming the shortlist is the half a model is good at -- it knows a thumb
    problem from a reach problem -- and driving the chosen number is the half
    it is bad at and the search is good at. So the model narrows, and the
    search still decides which of the survivors wins and by how much.

    A name is either a super primitive or an atomic "part:move".
    """
    wanted = set(names)
    for primitive in super_primitives(hand):
        if wanted and primitive.name not in wanted:
            continue
        if parts and not (set(primitive.parts) & set(parts)):
            continue
        for amount in magnitudes:
            try:
                rotations = primitive.solve(sensing, hand, amount)
            except Exception:  # noqa: BLE001
                continue
            if rotations:
                yield primitive.name, amount, rotations
    # The atomic layer is on the menu only when asked for by name. Sweeping it
    # is what costs; a model that wants one joint moved can still say so.
    for name in sorted(n for n in wanted if ":" in n):
        part, _, move = name.partition(":")
        if parts and part not in parts:
            continue
        for amount in magnitudes:
            try:
                rotations = move_rotations(part, move, amount)
            except Exception:  # noqa: BLE001
                continue
            if rotations:
                yield name, amount, rotations


def candidate_moves(step: Step) -> dict[str, tuple[str, ...]]:
    """The moves each active part may run this frame."""
    return {part: tuple(moves_for(part)) for part in step.active_parts}



# ---------------------------------------------------------------------------
# Numerical targets: the model names a number, the search drives it there.
#
# Choosing one primitive a second is the wrong job for a model. It reasons well
# about WHAT should be true -- "the thumb and index should point at each other,
# that is a dot product of -1" -- and badly about which of twenty-two controls
# moves that number, which is a search problem it cannot run and a numeric
# optimiser can, thirty times a second instead of once.
#
# So the model sets a target and the greedy controller pursues it every frame.
# The division is the one the two are actually good at.
# ---------------------------------------------------------------------------

#: Everything the model may aim at, and how to read it.
METRICS: dict[str, Any] = {}

#: Readable, but not targetable. A number nothing can move is a number a plan
#: can only get stuck on: measured across the whole vocabulary at a mid-reach
#: pose, no control changes either of these, and both read identically at the
#: rest pose and 90 cm later. Offering them as goals is offering a stall.
UNTARGETABLE = frozenset({
    "aperture_deg",
    "thumb_to_fingers_m",
    # The old C measures, kept readable and retired as goals. They described a
    # hand that had already closed -- rays aimed at each other -- so c_closure
    # could not leave its pinned value above a 4.4 cm opening while the block
    # needing to enter was 6.0 cm wide. There was no posture that both admitted
    # this object and scored as a C. grip_parallel, grip_tip_spread_m and
    # grip_base_spread_m describe the OPEN shape instead, which is the one a
    # hand has to reach before it can close on anything.
    "c_closure",
    "rays_toward",
    "ray_gap_m",
    # And the trap: nine controls move it, no control hurts it, and a hand
    # splayed perfectly flat scores full marks.
    "ray_dot",
    # thumb_opposition reads well and steers badly. Measured at a mid-reach
    # pose it is contested six ways against ten -- most of what moves it makes
    # the grasp worse -- and it is satisfied by a thumb across the object
    # whether or not anything is between them. It has now consumed three runs
    # on its own: 000489 asked for 0.8 eight times while nothing could deliver
    # it, 000495 spent nineteen of twenty-two calls chasing it, and 000496
    # reached 5.9 cm from a grasp and then drifted back out to 14.6 doing the
    # same. The shape it describes is real; steering by it is not.
    #
    # What replaced it: grip_parallel, grip_tip_spread_m and grip_base_spread_m
    # say the same thing about the hand and can each be driven.
    "thumb_opposition",
    # grip_closure has no movers left. It averages the old aimed-at-each-other
    # C over four fingers, so it inherits that measure's dead zone: pinned at
    # +1.000 at every pose reached in practice, with nothing in the vocabulary
    # able to shift it. grip_parallel and the two spreads describe the same
    # hand and each respond to something.
    "grip_closure",
})


def targetable() -> tuple[str, ...]:
    """The metrics a goal may name."""
    _register_metrics()
    return tuple(sorted(set(METRICS) - UNTARGETABLE))


def _register_metrics() -> None:
    if METRICS:
        return
    METRICS.update({
        # -1 is a C: thumb and index rays parallel and opposite. +1 is a blade.
        # Antiparallel AND converging. -1 is a C that closes around something.
        # Prefer this over raw ray_dot, which a splayed-open hand also satisfies.
        "c_closure": lambda s, h: c_shape(s.bones, h)["c_closure"],
        # The whole hand: mean C across all four fingers. -1 is a grip.
        "grip_closure": lambda s, h: grip_closure(s.bones, h),
        # Metres from the object to the line between thumb and fingers. 0 means
        # the object is INSIDE the hand's opening rather than beside it.
        "object_in_grasp_m": lambda s, h: object_in_grasp(s, h),
        "ray_dot": lambda s, h: c_shape(s.bones, h)["ray_dot"],
        "rays_toward": lambda s, h: c_shape(s.bones, h)["toward"],
        # Metres by which the two fingertip rays miss each other.
        "ray_gap_m": lambda s, h: c_shape(s.bones, h)["gap_m"],
        # Palm centre to the object's SURFACE, metres. What decides whether a
        # grasp is possible, where the fingertip-to-centre distance below is
        # minimised by driving the fingers into the object.
        "palm_to_object_m": palm_to_object_m,
        # +1 when the palm looks straight at the face being approached. A hand
        # 2 cm away and edge-on cannot grasp; nothing measured that.
        "palm_facing": palm_facing,
        # Fingertip mean to the object, metres.
        "tips_to_object_m": lambda s, h: float(
            np.linalg.norm(s.convergence - s.object_position)
        ),
        # +1 when the thumb is directly across the object from the fingers.
        "thumb_opposition": lambda s, h: thumb_opposition_score(s),
        # Metres from the thumb tip to the middle of the finger group.
        "thumb_to_fingers_m": lambda s, h: _thumb_to_fingers(s),
        # THE grip shape, in three numbers. Open: thumb and fingers pointing the
        # same way, tips wide, bases wide -- a C. Then close, which shrinks the
        # tip spread alone with every curl held.
        "grip_parallel": grip_parallel,
        "grip_tip_spread_m": grip_tip_spread_m,
        "grip_base_spread_m": grip_base_spread_m,
        # +1 when the thumb and fingers are level with each other, so the
        # object can sit BETWEEN them; 0 when they are stacked on one face.
        # This is what level_wrist moves, and nothing else moves it: it is the
        # "opposite sides" half of a grasp, which had no number until now and so
        # could never be asked for.
        "digits_straddle": digits_straddle,
        # Degrees the apertures stand off the palm. Kept as a reading and NOT
        # as a target: it does not move between the rest pose and a mid-reach
        # one, no control was found to change it, and a number nothing can move
        # is a number a plan can only get stuck on.
        "aperture_deg": lambda s, h: __import__(
            "rigby_poc.skills", fromlist=["x"]
        ).aperture_orthogonality_deg(s.bones, h.value),
    })


@dataclass
class NumericTarget:
    """A number the model wants, and what it is currently."""

    metric: str
    value: float
    set_at_s: float = 0.0
    #: Further (metric, value) pairs pursued at the same time, each weighted.
    #: One number at a time is how a hand ends up satisfying a shape while
    #: drifting out of reach: every metric here is contested by controls that
    #: improve one and wreck another, and a search told to care about exactly
    #: one of them will happily pay any price in the others. Naming the set is
    #: the model's job, because which numbers matter together is a judgement
    #: about the task and not something the search can read off the geometry.
    also: tuple[tuple[str, float, float], ...] = ()
    #: Which controls may be used to reach it. The model names these alongside
    #: the number, because "make the thumb oppose the index" is two statements:
    #: what should become true, and which part of the body is meant to do it.
    using: tuple[str, ...] = ()

    def error(self, sensing: Sensing, hand: Hand) -> float:
        """Distance from the whole set of numbers, weighted.

        Each term is scaled by how far the metric started from its goal, so a
        distance in metres and a dot product in the range -1..1 contribute
        comparably. Without that the metre-scale terms vanish next to the
        others and the search quietly optimises only the unit-scale ones.
        """
        _register_metrics()
        total = 0.0
        for metric, value, weight in self._terms():
            reader = METRICS.get(metric)
            if reader is None:
                continue
            try:
                total += weight * abs(float(reader(sensing, hand)) - float(value))
            except Exception:  # noqa: BLE001
                continue
        return total

    def _terms(self) -> tuple[tuple[str, float, float], ...]:
        every = ((self.metric, self.value, 1.0),) + tuple(self.also)
        return tuple(term for term in every if term[0] not in UNTARGETABLE)

    def reached(self, sensing: Sensing, hand: Hand) -> bool:
        """Every named number is where it was asked to be."""
        _register_metrics()
        for metric, value, _weight in self._terms():
            reader = METRICS.get(metric)
            if reader is None:
                continue
            tolerance = 0.01 if metric.endswith("_m") else 0.05
            try:
                if abs(float(reader(sensing, hand)) - float(value)) > tolerance:
                    return False
            except Exception:  # noqa: BLE001
                continue
        return True

    def to_dict(self) -> dict[str, Any]:
        return {"metric": self.metric, "value": self.value,
                "also": [list(a) for a in self.also],
                "using": list(self.using)}


def pursue_target(
    sensing: Sensing,
    hand: Hand,
    target: NumericTarget,
    magnitudes: tuple[float, ...] = (
        -1.0, -0.7, -0.4, -0.15, 0.15, 0.4, 0.7, 1.0),
) -> tuple[str, float, dict[str, Any]]:
    """The greedy half: whichever control moves the number closest to target.

    Scored only by the named metric, over whichever controls the target allows.
    This is the search the model cannot do and does not need to: it has already
    said what the number should be, and which controls are meant to get it
    there.
    """
    here = target.error(sensing, hand)
    best: tuple[float, str, float, dict[str, Any]] = (here, "hold", 0.0, {})
    for name, amount, rotations in _candidates(
        sensing, hand, tuple(target.using), magnitudes
    ):
        trial = dict(sensing.bones)
        for bone, rotation in rotations.items():
            trial[bone] = BonePose(rotation=rotation)
        probe = sense(
            trial, hand, sensing.object_position, sensing.contact_force_n,
            sensing.opposed, sensing.time_s,
        )
        value = target.error(probe, hand)
        if value < best[0] - 1e-6:
            best = (value, name, amount, rotations)
    return best[1], best[2], best[3]


@dataclass
class Trace:
    """What the loop decided, and what it was reading when it decided it."""

    steps: list[dict[str, Any]] = field(default_factory=list)
    decisions: list[dict[str, Any]] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "protocol": "closed_loop_generation_v1",
            "steps": self.steps,
            "decisions": self.decisions,
        }


#: How far the fingers start curled. Fitted against the block: the C measure
#: only comes alive at 0.6, where the opening has already narrowed to 4.4 cm and
#: the block is 6.0 -- so a hand curled enough to register a C is a hand the
#: block cannot enter. 0.4 is the closed-most posture that still admits it.
#:
#:     curl   toward   c_closure   opening
#:      0.4   -0.266    +1.000      6.1 cm   <- block fits
#:      0.6   +0.008    +0.076      4.4 cm   <- C live, block excluded
#:      1.0   +0.806    -0.667      1.1 cm
#:
#: That gap is a real mismatch between the hand's aperture and the object, not a
#: tuning choice, and it is why no run has produced a C on this block.
_PRE_GRASP_CURL = 0.22


def _pre_grasp_pose(hand: Hand) -> dict[str, BonePose]:
    """The hand a grasp starts from: thumb across the palm, fingers part-curled.

    The rig's neutral hand is flat with the thumb alongside the fingers pointing
    the same way -- a karate chop, not a hand about to pick something up. Every
    run has opened there and spent its first decisions leaving, and run 000489
    spent all twenty-six of them: twenty-two thumb moves that could not raise
    the C measure off its pinned value, because the C takes the WORSE of the two
    rays and a straight index is always the worse one.
    """
    pose = {
        bone: BonePose(rotation=rotation)
        for bone, rotation in _thumb_home_rotations(hand).items()
    }
    empty = observe({}, hand, np.zeros(3), np.zeros(3), {}, False, 0.0)
    for primitive in super_primitives(hand):
        if not primitive.name.startswith("curl_"):
            continue
        try:
            rotations = primitive.solve(empty, hand, _PRE_GRASP_CURL)
        except Exception:  # noqa: BLE001
            continue
        for bone, rotation in rotations.items():
            pose[bone] = BonePose(rotation=rotation)
    return pose


def generate(
    situation: MotionSituation,
    scene: SceneManifest,
    hand: Hand,
    *,
    selector: MoveSelector | None = None,
    fps: float = 30.0,
    max_seconds: float = 4.0,
) -> tuple[list[Any], Trace]:
    """Run the loop and return the frames it produced.

    The simulation is stepped INSIDE the loop, and every sensor reading comes
    out of it. That is the whole difference from the old generator, which
    authored a motion, simulated it afterwards, and had no way for the result to
    influence anything.
    """
    import mujoco

    from .models import ClipFrame, Transform
    from .physics import (
        _contact_digit,
        _contact_snapshot,
        _embodied_xml,
        _frame_hand_landmarks,
        _hand_segment_pairs,
        _opposing_contact,
        _seed_embodied_bodies,
        _set_embodied_mocap,
        mj_to_app_position,
    )

    figure = scene.object_by_id(situation.figure)
    if figure is None:
        raise ValueError(f"figure {situation.figure!r} is not in the scene")
    selector = selector or SuperPrimitiveSelector(hand=hand)
    steps = decompose(situation, scene, hand)
    # A selector that plans for itself is not marched through mine.
    if hasattr(selector, "make_plan"):
        steps = [_free_step(situation, scene, hand)]
    trace = Trace(steps=[s.to_dict() for s in steps])

    kinematics = rig_kinematics()
    # The thumb starts where a grasp starts. The rig's neutral thumb lies
    # alongside the fingers pointing the same way, which is not a hand about to
    # pick something up, and every run so far has opened by spending its first
    # decisions trying to leave that pose.
    pose: dict[str, BonePose] = _pre_grasp_pose(hand)
    segment_pairs = _hand_segment_pairs(hand)

    # Sized from the open hand, as the embodied simulation does.
    opening = ClipFrame(time_s=0.0, bones=pose, objects={})
    landmarks = _frame_hand_landmarks(opening, hand)
    lengths = {}
    for name, (start, end) in segment_pairs.items():
        digit = name.split("_")[1]
        tip = landmarks[f"{hand.value}{digit.title()}Tip"] if end is None else landmarks[end]
        lengths[name] = max(0.002, float(np.linalg.norm(tip - landmarks[start])) * 0.5 - 0.003)
    across = float(np.linalg.norm(
        landmarks[f"{hand.value}IndexProximal"] - landmarks[f"{hand.value}LittleProximal"]))
    along = float(np.linalg.norm(
        landmarks[f"{hand.value}MiddleProximal"] - landmarks[f"{hand.value}Hand"]))
    palm_half = np.asarray([max(0.025, across * 0.55), max(0.028, along * 0.58), 0.012])

    # A camera carried on a mocap body at the head. The embodied model has no
    # head -- it is hand geometry and the object -- so the eye is added here and
    # driven each frame from the rendered skeleton, which keeps the image the
    # model sees tied to where the body is actually looking.
    xml = _embodied_xml(figure, palm_half, lengths, scene.support_height_m)
    # Lit, because the embodied model declares no lights at all and a scene
    # rendered by the default headlight alone came out at a mean brightness of
    # 31 out of 255 -- dark enough that a model would be guessing.
    eye = (
        '<light name="key" pos="0.6 -1.0 2.6" dir="-0.2 0.4 -1" diffuse="1 1 1"/>'
        '<light name="fill" pos="-0.8 -1.0 2.0" dir="0.3 0.4 -1" '
        'diffuse="0.5 0.5 0.5"/>'
        '<body name="ego_eye" mocap="true" pos="0 0 1.6">'
        '<camera name="ego" fovy="75" pos="0 0 0"/>'
        "</body>"
    )
    xml = xml.replace("</worldbody>", eye + "</worldbody>", 1)
    model = mujoco.MjModel.from_xml_string(xml)
    data = mujoco.MjData(model)
    block_body = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "block")
    _seed_embodied_bodies(model, data, landmarks, hand, segment_pairs)
    mujoco.mj_forward(model, data)

    # The object's actual shape, so the approach can aim at a FACE of it.
    figure_half = np.asarray([
        float(figure.dimensions_m.x) / 2.0,
        float(figure.dimensions_m.y) / 2.0,
        float(figure.dimensions_m.z) / 2.0,
    ])
    dt = float(model.opt.timestep)
    steps_per_frame = max(1, int(round((1.0 / fps) / dt)))
    frames: list[ClipFrame] = []
    index = 0
    spent = 0
    #: Where the object was last SEEN. None until it has been looked at once.
    remembered: np.ndarray | None = None
    best_error = float("inf")
    stalled = 0
    previous_object: np.ndarray | None = None
    previous_hand: np.ndarray | None = None

    for frame_index in range(int(max_seconds * fps)):
        now = frame_index / fps
        # ---- sense, from the simulation that is running ----
        _names, _pen, details = _contact_snapshot(model, data)
        forces: dict[str, float] = {}
        for geom, _position, force, _normal in details:
            digit = _contact_digit(geom)
            if digit is not None:
                forces[digit] = max(forces.get(digit, 0.0), float(force))
        opposed = _opposing_contact(details) is not None
        truth = mj_to_app_position(data.xpos[block_body])
        step_s = 1.0 / fps
        object_velocity = (
            (truth - previous_object) / step_s if previous_object is not None
            else np.zeros(3)
        )
        previous_object = np.asarray(truth, dtype=float)
        hand_now = rig_kinematics().canonical_positions(pose).get(
            f"{hand.value}Hand") if pose else None
        hand_velocity = (
            (np.asarray(hand_now) - previous_hand) / step_s
            if hand_now is not None and previous_hand is not None else np.zeros(3)
        )
        if hand_now is not None:
            previous_hand = np.asarray(hand_now, dtype=float)
        reading = observe(pose, hand, truth, remembered, forces, opposed, now,
                          object_velocity, hand_velocity,
                          object_half_m=figure_half)
        if reading.in_view:
            remembered = np.asarray(reading.object_position, dtype=float)

        # ---- has this product been achieved? ----
        step = steps[index]
        # Give up when nothing is getting better. One run spent seventeen calls
        # and eight seconds working a stage whose object had already been
        # knocked out of reach, each decision sound and none of them able to
        # help. A loop that cannot tell "hard" from "hopeless" pays for the
        # difference indefinitely.
        current_error = step.error(reading)
        if current_error < best_error - _PROGRESS_EPSILON_M:
            best_error, stalled = current_error, 0
        else:
            stalled += 1
        if stalled >= (step.stall_frames or _STALL_FRAMES):
            trace.decisions.append({
                "time_s": round(now, 3), "step": step.name, "event": "stalled",
                "error": round(current_error, 5),
                "best_error": round(best_error, 5),
                "loaded": list(reading.loaded_digits()), "opposed": opposed})
            break
        # Tell the selector where it is, so it can decide to move.
        if hasattr(selector, "plan"):
            selector.plan = tuple(s.name for s in steps)
            selector.stage_index = index
        if hasattr(selector, "make_plan") and not getattr(selector, "own_plan", None):
            selector.make_plan(situation.source_text or "pick up the object")
        if hasattr(selector, "scene_context") and not selector.scene_context:
            # What else is in the world. Without it the model reasons about a
            # block in a void and cannot tell that the surface under it is a
            # table it must not drive the hand through.
            selector.scene_context = {
                "grasping": figure.id,
                "support_height_m": round(float(scene.support_height_m), 3),
                "objects": [
                    {
                        "id": item.id,
                        "size_m": [
                            round(item.dimensions_m.x, 3),
                            round(item.dimensions_m.y, 3),
                            round(item.dimensions_m.z, 3),
                        ],
                        "at": [
                            round(item.transform.translation.x, 3),
                            round(item.transform.translation.y, 3),
                            round(item.transform.translation.z, 3),
                        ],
                    }
                    for item in scene.objects
                ],
            }
        if step.reached(reading):
            trace.decisions.append({
                "time_s": round(now, 3), "step": step.name,
                "event": "reached", "error": round(step.error(reading), 5)})
            if index + 1 < len(steps):
                index += 1
                spent = 0
                step = steps[index]
        elif spent >= step.budget_frames and not _stage_controlled(selector):
            # A timer only advances the plan when nothing else can. With a
            # selector that owns progression this is off entirely, because
            # advancing on a clock is what produced the punch: the plan reached
            # "close" while the hand was still 19 cm away, closed it, and then
            # the next stage reached in with the hand already shut.
            trace.decisions.append({
                "time_s": round(now, 3), "step": step.name,
                "event": "budget_exhausted", "error": round(step.error(reading), 5)})
            if index + 1 < len(steps):
                index += 1
                spent = 0
                step = steps[index]

        # ---- decide what each part does this instant ----
        action, amount, rotations = selector.choose(reading, step)
        spent += 1
        if action == "abandon":
            trace.decisions.append({
                "time_s": round(now, 3), "step": step.name, "event": "abandoned",
                "error": round(step.error(reading), 5),
                "loaded": list(reading.loaded_digits()), "opposed": opposed})
            break
        if action in ("next_stage", "previous_stage"):
            moved = 1 if action == "next_stage" else -1
            new_index = int(np.clip(index + moved, 0, len(steps) - 1))
            trace.decisions.append({
                "time_s": round(now, 3), "step": step.name, "event": action,
                "to": steps[new_index].name,
                "error": round(step.error(reading), 5),
                "loaded": list(reading.loaded_digits()), "opposed": opposed})
            index, spent = new_index, 0
            # A deliberate change of stage is progress, so the stall counter
            # restarts rather than punishing the loop for having reconsidered.
            best_error, stalled = float("inf"), 0
            rotations = {}
        if True:
            trace.decisions.append({
                "time_s": round(now, 3), "step": step.name, "event": "chose",
                "action": action, "amount": amount,
                "error": round(step.error(reading), 5),
                "loaded": list(reading.loaded_digits()), "opposed": opposed,
                "in_view": reading.in_view,
                "gaze_error_deg": round(reading.gaze_error_deg, 1)})

        # ---- move toward the chosen pose, at a bounded rate ----
        target = dict(pose)
        # Keeping the eyes on the work runs alongside whatever the body is
        # doing, rather than competing with it for the one decision. Asked to
        # choose ONE action, a selector always has something more urgent than
        # looking, so the head never moved for the whole of the last run -- and
        # a head that never turns is a camera pointed at nothing, which is the
        # image the brain is being asked to reason from.
        for bone, rotation in _track_with_head(pose, reading).items():
            target[bone] = BonePose(rotation=rotation)
        for bone, rotation in rotations.items():
            target[bone] = BonePose(rotation=rotation)

        # ---- move toward it, bounded by the joint speed ceilings ----
        # A bone absent from the pose starts from rest rather than being exempt,
        # so the ceilings bind from the first frame. Without that the hand
        # crossed 0.9 m in four frames and reached its standoff before the
        # second decision was taken, which is a teleport with sensing attached
        # rather than a loop.
        # NOT rate-limited for proximity. The near-contact ceilings exist and
        # are measured, and applying them destroys the grasp: the digits cannot
        # close in time, and the lift goes from 19.99 cm to 1.31 at 45 deg/s and
        # is still gone at 160. The block's peak speed is 0.46 m/s either way,
        # so they were not buying what they were meant to buy.
        #
        # They were written to stop a thumb at 0.49 m/s throwing the block, and
        # that turned out to be a symptom of digits welded rigidly to their
        # commanded poses. Compliant welds and closure that stops at contact fix
        # the cause; slowing the hand only treated the outcome. The mechanism
        # stays in motion_limits for a future use, unwired.
        pose = _rate_limited(
            pose, _blend(pose, target, getattr(selector, "rate", 0.25)), 1.0 / fps
        )

        # ---- drive the simulation from the pose actually taken ----
        _aim_eye(model, data, pose, hand)
        if hasattr(selector, "pending_image"):
            selector.pending_image = selector.render(model, data)

        current = ClipFrame(time_s=now, bones=pose, objects={})
        _set_embodied_mocap(
            model, data, _frame_hand_landmarks(current, hand), hand, segment_pairs)
        for _ in range(steps_per_frame):
            mujoco.mj_step(model, data)

        placed = mj_to_app_position(data.xpos[block_body])
        # EVERY object in the scene, not only the one being grasped. A clip is
        # supposed to describe the scene it came from, and the exporter reads
        # each object's track out of the frames -- so a clip carrying only the
        # figure raises KeyError on the first prop the scene happens to contain.
        # It cost a completed run whose frames were discarded on the way to
        # disk, which is a worse failure than not rendering, because the calls
        # had already been spent.
        #
        # Only the figure moves; the rest stand where the scene put them.
        moment = {
            item.id: item.transform.model_copy(deep=True)
            for item in scene.objects if item.id != figure.id
        }
        moment[figure.id] = Transform(translation=Vec3(
            x=float(placed[0]), y=float(placed[1]), z=float(placed[2])))
        frames.append(ClipFrame(time_s=now, bones=dict(pose), objects=moment))
    return frames, trace


#: An improvement smaller than this is not one.
_PROGRESS_EPSILON_M = 0.002

#: Frames without improvement before the attempt is called off. Three seconds
#: at 30 fps, which is four decisions at the model's cadence -- long enough to
#: work a hard stage, short enough not to fund a hopeless one.
_STALL_FRAMES = 90


def _stage_controlled(selector: Any) -> bool:
    """Whether the selector decides its own place in the plan."""
    return hasattr(selector, "plan")


def _track_with_head(
    pose: dict[str, BonePose], sensing: Sensing
) -> dict[str, Any]:
    """Aim the eyes at the work. Runs every frame, under whatever else is chosen."""
    from .gaze_controller import aim_gaze

    try:
        return dict(aim_gaze(pose, sensing.object_position).bones)
    except Exception:  # noqa: BLE001
        return {}


def _aim_eye(model: Any, data: Any, pose: dict[str, BonePose], hand: Hand) -> None:
    """Put the camera at the head, pointing where the head points."""
    import mujoco

    from .physics import _APP_TO_MJ, _mj_quaternion

    kinematics = rig_kinematics()
    try:
        positions = kinematics.canonical_positions(pose)
        rotation = kinematics.canonical_world_rotation(pose, "head")
    except Exception:
        return
    target = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "ego_eye")
    if target < 0:
        return
    index = int(model.body_mocapid[target])
    if index < 0:
        return
    data.mocap_pos[index] = _APP_TO_MJ @ np.asarray(positions["head"], dtype=float)
    # A ROTATION changes frames as M R M-transpose, not M R. Written the second
    # way the camera pointed into empty space and rendered pure black at every
    # orientation I tried -- a VLM would have been handed blank frames and asked
    # what it saw. Verified by brightness: 0.0 wrong, 95.7 right.
    data.mocap_quat[index] = _mj_quaternion(
        _APP_TO_MJ @ rotation @ _APP_TO_MJ.T
    )


def _rate_limited(
    current: dict[str, BonePose], target: dict[str, BonePose], dt: float,
    near_contact: bool = False,
) -> dict[str, BonePose]:
    """Clamp each bone's per-frame rotation to its joint class's ceiling.

    Two ceilings: the ordinary one for travel, and a much lower one once the
    hand is within a few centimetres of the object. See the manifest's
    ``near_contact_rate_limits`` for why -- briefly, the digits are welded to
    commanded poses and cannot be slowed by what they hit, so a speed that is
    unremarkable in the air is a strike on arrival.
    """
    from scipy.spatial.transform import Rotation, Slerp

    from .models import Quat
    from .motion_limits import limit_for

    from .models import Quat as _Quat

    #: A bone absent from the pose is at its rest rotation, not exempt. Passing
    #: absent bones through unlimited meant the ceilings did not engage until a
    #: bone already existed -- and since the pose starts empty, the first frames
    #: were unbounded. The hand crossed 0.9 m in four frames and "reached" its
    #: standoff before the second decision was made.
    rest = _Quat(x=0.0, y=0.0, z=0.0, w=1.0)
    out = dict(current)
    for bone, pose in target.items():
        start = current.get(bone) or BonePose(rotation=rest)
        a, b = start.rotation, pose.rotation
        rotations = Rotation.from_quat([[a.x, a.y, a.z, a.w], [b.x, b.y, b.z, b.w]])
        delta = float(np.degrees((rotations[1] * rotations[0].inv()).magnitude()))
        ceiling = limit_for(bone, near_contact) * dt
        if delta <= ceiling or delta < 1e-9:
            out[bone] = pose
            continue
        xyzw = Slerp([0.0, 1.0], rotations)([ceiling / delta]).as_quat()[0]
        out[bone] = BonePose(rotation=Quat(
            x=float(xyzw[0]), y=float(xyzw[1]), z=float(xyzw[2]), w=float(xyzw[3])))
    return out


def _blend(
    current: dict[str, BonePose], target: dict[str, BonePose], rate: float
) -> dict[str, BonePose]:
    """Move a fraction of the way toward the target, about the shortest arc."""
    from scipy.spatial.transform import Rotation, Slerp

    from .models import Quat

    out = dict(current)
    for bone, pose in target.items():
        start = current.get(bone)
        if start is None:
            out[bone] = pose
            continue
        a = start.rotation
        b = pose.rotation
        rotations = Rotation.from_quat([[a.x, a.y, a.z, a.w], [b.x, b.y, b.z, b.w]])
        xyzw = Slerp([0.0, 1.0], rotations)([float(np.clip(rate, 0.0, 1.0))]).as_quat()[0]
        out[bone] = BonePose(rotation=Quat(
            x=float(xyzw[0]), y=float(xyzw[1]), z=float(xyzw[2]), w=float(xyzw[3])))
    return out


def compile_closed_loop(
    prompt: str,
    scene: SceneManifest,
    hand: Hand,
    *,
    selector: MoveSelector | None = None,
    fps: float = 30.0,
    max_seconds: float = 6.0,
) -> Any:
    """Run the loop and return a ClipResult, so the pipeline can carry it.

    This is the seam. ``run_best_of_five`` never defined what a candidate is --
    it calls something that returns a ClipResult, then captures, judges, ranks
    and repairs it -- so a clip produced by deciding each frame drops into the
    same flywheel as one produced by interpolating seven authored phases, and
    the two can be judged against each other.
    """
    from importlib.metadata import version

    from .compiler import COMPILER_VERSION
    from .models import ClipResult, Failure, FailureCode, Provenance
    from .talmy import interpret

    situation = interpret(prompt, scene)
    if situation is None:
        raise ValueError(f"{prompt!r} does not resolve to a motion situation")

    frames, trace = generate(
        situation, scene, hand, selector=selector, fps=fps, max_seconds=max_seconds
    )
    reached = {
        d["step"] for d in trace.decisions if d.get("event") == "reached"
    }
    planned = [step["name"] for step in trace.steps]
    last = trace.decisions[-1] if trace.decisions else {}

    metrics: dict[str, Any] = {
        "generator": "closed_loop_v1",
        "closed_loop": trace.to_dict(),
        "steps_planned": len(planned),
        "steps_reached": len(reached),
        "goals_reached": [name for name in planned if name in reached],
        "final_error": last.get("error"),
        "opposed_at_end": bool(last.get("opposed", False)),
        "loaded_at_end": list(last.get("loaded", [])),
    }
    unmet = [name for name in planned if name not in reached]
    failure = None
    if unmet:
        # Named by the goal that was not reached, so the reason a clip failed is
        # the reading that failed rather than a generic verdict.
        failure = Failure(
            code=FailureCode.GRASP_UNSTABLE,
            message=f"{len(unmet)} of {len(planned)} goals not reached: {unmet[0]}",
            details={
                "unmet_goals": unmet,
                "final_error": last.get("error"),
                "opposed_at_end": bool(last.get("opposed", False)),
                "loaded_at_end": list(last.get("loaded", [])),
            },
            recoverable=True,
        )
    return ClipResult(
        # Success is every goal reached, judged from readings rather than from
        # the motion having run to the end. A clip that finished is not a clip
        # that worked, and conflating them is what let a hand closing on empty
        # air report a grasp.
        success=len(reached) == len(planned),
        fps=fps,
        duration_s=frames[-1].time_s if frames else 0.0,
        frames=frames,
        metrics=metrics,
        slider_observables={},
        parametric_observables={},
        failure=failure,
        provenance=Provenance(
            rig_id="mesh2motion-human-vrm1",
            rig_asset="assets/models/human-male.glb",
            compiler_version=COMPILER_VERSION,
            physics_engine="MuJoCo",
            physics_version=version("mujoco"),
            planner_provider="closed-loop",
            planner_model=type(selector or SuperPrimitiveSelector(hand=hand)).__name__,
            model_calls=0,
            seed=0,
            physics_model={
                "type": "closed loop, decided per frame from super primitives",
                "parallel_gripper_proxy": False,
                "free_block_joint": True,
                "simulation_stepped_inside_the_loop": True,
                "independent_contact_digits": [
                    "thumb", "index", "middle", "ring", "little"],
            },
            coordinate_frames={"up": "+Y", "units": "metres"},
        ),
    )
